    var PBRCommonGLSL = "#if !defined(pbrCommon_lib)\n    #define pbrCommon_lib\n\n// varying\nvarying vec3 v_PositionWS;\n\n// todo\nvarying vec3 v_NormalWS;\nvarying vec3 v_TangentWS;\nvarying vec3 v_BiNormalWS;\n\n    #ifdef UV\nvarying vec2 v_Texcoord0;\n    #endif // UV\n\n    #ifdef UV1\n\t#ifdef LIGHTMAP\nvarying vec2 v_Texcoord1;\n\t#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\nvarying vec4 v_VertexColor;\n    #endif // COLOR\n\n// 记录顶点信息, 用于由vs向fs传递数据\nstruct PixelParams {\n\n    vec3 positionWS;\n\n    vec3 normalWS;\n    vec3 tangentWS;\n    vec3 biNormalWS;\n    mat3 TBN;\n\n    #ifdef UV\n    vec2 uv0;\n    #endif // UV\n\n    #ifdef UV1\n\t#ifdef LIGHTMAP\n    vec2 uv1;\n\t#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\n    vec4 vertexColor;\n    #endif // COLOR\n};\n\n#endif // pbrCommon_lib";

    var PBRVertexGLSL = "#if !defined(pbrVertex_lib)\n    #define pbrVertex_lib\n\n    #include \"ShadingVertex.glsl\";\n\n    #ifdef THICKNESS\n// xyz: world scale, w: length(xyz)\nvarying vec4 v_WorldScale;\n    #endif // THICKNESS\n\nvoid initPixelParams(inout PixelParams params, in Vertex vertex)\n{\n    shadingPixelParams(params, vertex);\n    sharePixelParams(params);\n\n    #ifdef THICKNESS\n    mat4 worldMat = getWorldMatrix();\n    v_WorldScale.x = length(vec3(worldMat[0].xyz));\n    v_WorldScale.y = length(vec3(worldMat[1].xyz));\n    v_WorldScale.z = length(vec3(worldMat[2].xyz));\n    v_WorldScale.w = length(v_WorldScale.xyz);\n    #endif // THICKNESS\n}\n\n#endif // pbrVertex_lib";

    var PBRFragGLSL = "//兼容WGSL\n#if !defined(pbrFrag_lib)\n    #define pbrFrag_lib\n\n    #include \"PBRLighting.glsl\";\n\n    #ifdef THICKNESS\n// xyz: world scale, w: length(xyz)\nvarying vec4 v_WorldScale;\n    #endif // THICKNESS\n\nvoid getPixelInfo(inout PixelInfo info, const in PixelParams pixel, const in Surface surface)\n{\n    info.positionWS = pixel.positionWS;\n    info.vertexNormalWS = pixel.normalWS;\n\n    #ifdef TANGENT\n    info.normalWS = normalize(pixel.TBN * surface.normalTS);\n    #else // TANGENT\n    info.normalWS = pixel.normalWS;\n    #endif // TANGENT\n\n    info.tangentWS = pixel.tangentWS;\n    info.biNormalWS = pixel.biNormalWS;\n\n    info.viewDir = normalize(u_CameraPos - info.positionWS);\n    info.NoV = min(max(dot(info.normalWS, info.viewDir), MIN_N_DOT_V), 1.0);\n\n    info.dfg = prefilteredDFG_LUT(surface.perceptualRoughness, info.NoV);\n\n    #ifdef SHEEN\n    info.energyCompensation = vec3(1.0);\n    #else // SHEEN\n    info.energyCompensation = (1.0 + surface.f0 * (1.0 / info.dfg.y - 1.0));\n    #endif // SHEEN\n\n    #ifdef IRIDESCENCE\n    info.iridescenceFresnel = evalIridescence(1.0, surface.iridescenceIor, info.NoV, surface.iridescenceThickness, surface.f0);\n    #endif // IRIDESCENCE\n\n    #ifdef SHEEN\n    info.sheenDfg = prefilteredDFG_LUT(surface.sheenPerceptualRoughness, info.NoV).z;\n    info.sheenScaling = 1.0 - vecmax(surface.sheenColor) * info.sheenDfg;\n    #endif // SHEEN\n\n    #ifdef CLEARCOAT\n\t#ifdef CLEARCOAT_NORMAL\n    info.clearCoatNormal = normalize(pixel.TBN * surface.clearCoatNormalTS);\n\t#else // CLEARCOAT_NORMAL\n    info.clearCoatNormal = info.vertexNormalWS;\n\t#endif // CLEARCOAT_NORMAL\n    info.clearCoatNoV = min(max(dot(info.clearCoatNormal, info.viewDir), MIN_N_DOT_V), 1.0);\n    #endif // CLEARCOAT\n\n    #ifdef ANISOTROPIC\n    mat3 anisotropyTBN = mat3(info.tangentWS, info.biNormalWS * -1.0, info.normalWS);\n    info.anisotropicT = anisotropyTBN * normalize(vec3(surface.anisotropyDirection, 0.0));\n    info.anisotropicB = cross(info.vertexNormalWS, info.anisotropicT);\n    info.ToV = dot(info.anisotropicT, info.viewDir);\n    info.BoV = dot(info.anisotropicB, info.viewDir);\n    info.at = mix(surface.roughness, 1.0, pow2(surface.anisotropy));\n    info.ab = surface.roughness;\n    #endif // ANISOTROPIC\n\n    #ifdef THICKNESS\n    info.worldScale = v_WorldScale;\n    #endif // THICKNESS\n\n    #ifdef LIGHTMAP\n\t#ifdef UV1\n    info.lightmapUV = pixel.uv1;\n\t#endif // UV1\n    #endif // LIGHTMAP\n}\n\nvec3 PBRLighting(const in Surface surface, const in PixelInfo info)\n{\n    vec3 lightColor = vec3(0.0);\n    #ifdef DIRECTIONLIGHT\n    for (int i = 0; i < CalculateLightCount; i++)\n\t{\n\t    if (i >= DirectionCount) break;\n\t    DirectionLight directionLight = getDirectionLight(i, info.positionWS);\n\t    // if (directionLight.lightMode == LightMode_Mix)\n\t\t// {\n\t\t//     continue;\n\t\t// }\n        if (directionLight.lightMode != LightMode_Mix) {\n\t        Light light = getLight(directionLight);\n\t        lightColor += PBRLighting(surface, info, light) * light.attenuation;\n        }\n\t}\n    #endif // DIRECTIONLIGHT\n\n    #if defined(POINTLIGHT) || defined(SPOTLIGHT)\n    ivec4 clusterInfo = getClusterInfo(u_View, u_Viewport, info.positionWS, gl_FragCoord, u_ProjectionParams);\n    #endif // POINTLIGHT || SPOTLIGHT\n\n    #ifdef POINTLIGHT\n    for (int i = 0; i < CalculateLightCount; i++)\n\t{\n        #ifdef BREAK_TEXTURE_SAMPLE\n\t    if (i >= clusterInfo.x) break; //兼容WGSL\n        #endif\n\t    PointLight pointLight = getPointLight(i, clusterInfo, info.positionWS);\n\t    // if (pointLight.lightMode == LightMode_Mix)\n\t\t// {\n\t\t//     continue;\n\t\t// }\n        if (pointLight.lightMode != LightMode_Mix) {\n\t        Light light = getLight(pointLight, info.normalWS, info.positionWS);\n            #ifndef BREAK_TEXTURE_SAMPLE\n            if (i < clusterInfo.x)\n            #endif\n\t            lightColor += PBRLighting(surface, info, light) * light.attenuation;\n        }\n\t}\n    #endif // POINTLIGHT\n\n    #ifdef SPOTLIGHT\n    for (int i = 0; i < CalculateLightCount; i++)\n\t{\n        #ifdef BREAK_TEXTURE_SAMPLE\n\t    if (i >= clusterInfo.y) break; //兼容WGSL\n        #endif\n\t    SpotLight spotLight = getSpotLight(i, clusterInfo, info.positionWS);\n\t    // if (spotLight.lightMode == LightMode_Mix)\n\t\t// {\n\t\t//     continue;\n\t\t// }\n        if (spotLight.lightMode != LightMode_Mix) {\n\t        Light light = getLight(spotLight, info.normalWS, info.positionWS);\n            #ifndef BREAK_TEXTURE_SAMPLE\n            if (i < clusterInfo.y)\n            #endif\n\t            lightColor += PBRLighting(surface, info, light) * light.attenuation;\n        }\n\t}\n    #endif // SPOTLIGHT\n\n    vec3 giColor = PBRGI(surface, info);\n\n    vec3 color = lightColor + giColor;\n\n    #ifdef EMISSION\n    color += surface.emissionColor;\n    #endif //  EMISSION\n    return color;\n}\n\n#endif // pbrFrag_lib";

    var PBRMetallicGLSL = "#if !defined(PBRMetallic_lib)\n    #define PBRMetallic_lib\n\n    #include \"ShadingFrag.glsl\";\n\n    #include \"PBRFrag.glsl\";\n\nstruct SurfaceInputs {\n    vec3 diffuseColor;\n    float alpha;\n    float alphaTest;\n    float metallic;\n    float smoothness;\n    float occlusion;\n    vec3 emissionColor;\n    vec3 normalTS;\n\n    #ifdef CLEARCOAT\n    float clearCoat;\n    float clearCoatRoughness;\n\t#ifdef CLEARCOAT_NORMAL\n    vec3 clearCoatNormalTS;\n\t#endif // CLEARCOAT_NORMAL\n    #endif // CLEARCOAT\n\n    #ifdef ANISOTROPIC\n    float anisotropy;\n    vec2 anisotropyDirection;\n    #endif // ANISOTROPIC\n};\n\nvoid initSurface(inout Surface surface, const in SurfaceInputs inputs, const in PixelParams pixel)\n{\n    surface.alpha = inputs.alpha;\n\n    surface.normalTS = inputs.normalTS;\n\n    vec3 baseColor = inputs.diffuseColor;\n    float metallic = inputs.metallic;\n    float perceptualRoughness = 1.0 - inputs.smoothness;\n\n    // default ior 1.5\n    float ior = 1.5;\n    surface.ior = 1.5;\n    vec3 f0 = vec3(0.04, 0.04, 0.04);\n\n    surface.perceptualRoughness = clamp(perceptualRoughness, MIN_PERCEPTUAL_ROUGHNESS, 1.0);\n    surface.roughness = surface.perceptualRoughness * surface.perceptualRoughness;\n    surface.diffuseColor = computeDiffuse(baseColor, metallic);\n    surface.f0 = computeF0(f0, baseColor, metallic);\n    surface.f90 = computeF90(surface.f0);\n\n    surface.occlusion = inputs.occlusion;\n\n    #ifdef EMISSION\n    surface.emissionColor = inputs.emissionColor;\n    #endif // EMISSION\n\n    #ifdef CLEARCOAT\n    surface.clearCoat = inputs.clearCoat;\n    surface.clearCoatPerceptualRoughness = clamp(inputs.clearCoatRoughness, MIN_PERCEPTUAL_ROUGHNESS, 1.0);\n    surface.clearCoatRoughness = surface.clearCoatPerceptualRoughness * surface.clearCoatPerceptualRoughness;\n\t#ifdef CLEARCOAT_NORMAL\n    surface.clearCoatNormalTS = inputs.clearCoatNormalTS;\n\t#endif // CLEARCOAT_NORMAL\n    #endif // CLEARCOAT\n\n    #ifdef ANISOTROPIC\n    surface.anisotropy = inputs.anisotropy;\n    surface.anisotropyDirection = inputs.anisotropyDirection;\n    #endif // ANISOTROPIC\n}\n\nvec4 PBR_Metallic_Flow(const in SurfaceInputs inputs, in PixelParams pixel)\n{\n    #ifdef ALPHATEST\n    if (inputs.alpha < inputs.alphaTest)\n\t{\n\t    discard;\n\t}\n    #endif // ALPHATEST\n\n    Surface surface;\n    initSurface(surface, inputs, pixel);\n\n    PixelInfo info;\n    getPixelInfo(info, pixel, surface);\n\n    vec3 surfaceColor = vec3(0.0);\n    surfaceColor += PBRLighting(surface, info);\n\n    return vec4(surfaceColor, surface.alpha);\n}\n\n#endif // PBRMetallic_lib\n";

    const dfg_128 = "";
    const RGBDMaxRange = 255;
    class PBRDefaultDFG {
        static get defaultDFG() {
            return PBRDefaultDFG._defaultDFG;
        }
        static set defaultDFG(value) {
            PBRDefaultDFG._defaultDFG = value;
        }
        static DefaultDfgTexture() {
            let hdrBuffer = Laya.Base64Tool.decode(dfg_128);
            let hdrInfo = Laya.HDRTextureInfo.getHDRInfo(hdrBuffer);
            let supportFloatTex = Laya.LayaGL.renderEngine.getCapable(Laya.RenderCapable.TextureFormat_R32G32B32A32);
            let supportFloatLinearFiltering = Laya.LayaGL.renderEngine.getCapable(Laya.RenderCapable.Texture_FloatLinearFiltering);
            let tex;
            if (supportFloatTex && supportFloatLinearFiltering) {
                tex = new Laya.Texture2D(hdrInfo.width, hdrInfo.height, hdrInfo.format, false, false, false);
                tex.setHDRData(hdrInfo);
            }
            else {
                tex = new Laya.Texture2D(hdrInfo.width, hdrInfo.height, Laya.TextureFormat.R8G8B8A8, false, false, false);
                let pixelCount = hdrInfo.width * hdrInfo.height;
                let hdrPixelData = hdrInfo.readScanLine();
                let rgbdPixelData = new Uint8Array(pixelCount * 4);
                for (let index = 0; index < pixelCount; index++) {
                    let r = hdrPixelData[index * 4];
                    let g = hdrPixelData[index * 4 + 1];
                    let b = hdrPixelData[index * 4 + 2];
                    let maxRGB = Math.max(r, g, b, 1e-5);
                    let d = Math.max(1.0, RGBDMaxRange / maxRGB);
                    d = Math.min(1, Math.max(0, (d / 255)));
                    rgbdPixelData[index * 4] = Math.min(1, Math.max(0, (r * d))) * 255;
                    rgbdPixelData[index * 4 + 1] = Math.min(1, Math.max(0, (g * d))) * 255;
                    rgbdPixelData[index * 4 + 2] = Math.min(1, Math.max(0, (b * d))) * 255;
                    rgbdPixelData[index * 4 + 3] = d * 255;
                }
                tex.setPixelsData(rgbdPixelData, false, false);
            }
            tex.lock = true;
            tex.wrapModeU = Laya.WrapMode.Clamp;
            tex.wrapModeV = Laya.WrapMode.Clamp;
            tex.anisoLevel = 1;
            this._defaultDFG = tex;
        }
    }

