    var OutputTransformGLSL = "#if !defined(OutputTransform_lib)\n    #define OutputTransform_lib\n\nvec3 gammaCorrect(in vec3 color, float gammaValue)\n{\n    return pow(color, vec3(gammaValue));\n}\n\nvec4 gammaCorrect(in vec4 color)\n{\n    // todo color gamut gamma value\n    // default sRGB\n    float gammaValue = 1.0 / 2.2;\n    return vec4(gammaCorrect(color.rgb, gammaValue), color.a);\n}\n\nvec4 outputTransform(in vec4 color)\n{\n    #ifdef GAMMACORRECT\n    // render in linear, output gamma\n    return gammaCorrect(color);\n    #else // GAMMACORRECT\n    return color;\n    #endif // GAMMACORRECT\n}\n\n#endif // OutputTransform_lib\n";

    var BakedBoneMatrixSamplerGLSL = "#if !defined(BakeBoneAnimSampler_lib)\n    #define BakeBoneAnimSampler_lib\n\nmat4 loadBakedMatMatrix(float FramePos, float boneIndices, float offset)\n{\n    vec2 uv;\n    float PixelPos = FramePos + boneIndices * 4.0;\n    float halfOffset = offset * 0.5;\n    float uvoffset = PixelPos / u_SimpleAnimatorTextureSize;\n    uv.y = floor(uvoffset) * offset + halfOffset;\n    uv.x = mod(float(PixelPos), u_SimpleAnimatorTextureSize) * offset + halfOffset;\n    vec4 mat0row = texture2D(u_SimpleAnimatorTexture, uv);\n    uv.x += offset;\n    vec4 mat1row = texture2D(u_SimpleAnimatorTexture, uv);\n    uv.x += offset;\n    vec4 mat2row = texture2D(u_SimpleAnimatorTexture, uv);\n    uv.x += offset;\n    vec4 mat3row = texture2D(u_SimpleAnimatorTexture, uv);\n    mat4 m = mat4(mat0row.x, mat0row.y, mat0row.z, mat0row.w,\n\tmat1row.x, mat1row.y, mat1row.z, mat1row.w,\n\tmat2row.x, mat2row.y, mat2row.z, mat2row.w,\n\tmat3row.x, mat3row.y, mat3row.z, mat3row.w);\n    return m;\n}\n\n#endif // BakeBoneAnimSampler_lib";

    var MorphTargetGLSL = "#if !defined(MorphTarget_lib)\n    #define MorphTarget_lib\n\n    #ifdef GRAPHICS_API_GLES3\n\n/// static mesh property\nuniform sampler2DArray u_MorphTargetsTex;\n// xy: tex size, z: attribute count\nuniform vec4 u_MorphParams;\nuniform vec4 u_MorphAttrOffset;\n\n\t#define Morph_TexWidth\t   u_MorphParams.x\n\t#define Morph_TexHeight\t   u_MorphParams.y\n\t#define Morph_AttributeNum u_MorphParams.z\n\t#define Morph_TargetNum\t   u_MorphParams.w\n\n\t#define Morph_PositionOffset u_MorphAttrOffset.x\n\t#define Morph_NormalOffset   u_MorphAttrOffset.y\n\t#define Morph_TangentOffset  u_MorphAttrOffset.z\n\n//#define MORPH_MAX_COUNT 32 //兼容WGSL\n\n/// dynamic params\n//uniform float u_MorphActiveTargets[MORPH_MAX_COUNT];\n//uniform float u_MorphTargetWeights[MORPH_MAX_COUNT];\nuniform vec4 u_MorphActiveTargets[MORPH_MAX_COUNT];\nuniform int u_MorphTargetActiveCount;\n\n\t#define MORPH_ACTIVE_COUNT u_MorphTargetActiveCount\n\nvec4 sampleMorphTargets(in int vertexID, in float targetID)\n{\n    int v = vertexID / int(Morph_TexWidth);\n    int u = vertexID - v * int(Morph_TexWidth);\n\n    vec3 uvw = vec3((float(u) + 0.5) / Morph_TexWidth, (float(v) + 0.5) / Morph_TexHeight, targetID);\n\n    return texture(u_MorphTargetsTex, uvw);\n}\n\nvec3 positionMorph(in vec3 position)\n{\n    int vertexID = gl_VertexID * int(Morph_AttributeNum) + int(Morph_PositionOffset);\n\n    for (int i = 0; i < MORPH_ACTIVE_COUNT; i++)\n\t{\n\t    float index = u_MorphActiveTargets[i].x;\n\t\tfloat weight = u_MorphActiveTargets[i].y;\n\n\t    position += sampleMorphTargets(vertexID, index).xyz * weight;\n\t}\n\n    return position;\n}\n\nvec3 normalMorph(in vec3 normal)\n{\n    int vertexID = gl_VertexID * int(Morph_AttributeNum) + int(Morph_NormalOffset);\n    for (int i = 0; i < MORPH_ACTIVE_COUNT; i++)\n\t{\n\t    float index = u_MorphActiveTargets[i].x;\n\t\tfloat weight = u_MorphActiveTargets[i].y;\n\n\t    normal += sampleMorphTargets(vertexID, index).xyz * weight;\n\t}\n\n    return normal;\n}\n\nvec4 tangentMorph(in vec4 tangent)\n{\n    int vertexID = gl_VertexID * int(Morph_AttributeNum) + int(Morph_TangentOffset);\n    for (int i = 0; i < MORPH_ACTIVE_COUNT; i++)\n\t{\n\t    float index = u_MorphActiveTargets[i].x;\n\t\tfloat weight = u_MorphActiveTargets[i].y;\n\n\t    vec4 sampleTangent = sampleMorphTargets(vertexID, index);\n\n\t    tangent.xyz += sampleTangent.xyz * weight * tangent.w * sampleTangent.w;\n\t}\n\n    return tangent;\n}\n\n    #endif // GRAPHICS_API_GLES3\n\n#endif // MorphTarget_lib";

    var VertexGLSL = "#if !defined(VertexCommon_lib)\n    #define VertexCommon_lib\n\n    #ifdef MORPHTARGETS\n\t#include \"MorphTarget.glsl\";\n    #endif // MORPHTARGETS\n\nstruct Vertex {\n\n    vec3 positionOS;\n\n    vec3 normalOS;\n\n    #ifdef TANGENT\n    vec4 tangentOS;\n    #endif // TANGENT\n\n    // todo  uv define ?\n    #ifdef UV\n    vec2 texCoord0;\n    #endif // UV\n\n    #ifdef UV1\n    vec2 texCoord1;\n    #endif // UV1\n\n    #ifdef COLOR\n    vec4 vertexColor;\n    #endif // COLOR\n\n    #ifdef LIGHTMAP\n    vec4 lightmapScaleOffset;\n\t#endif LIGHTMAP\n};\n\n/**\n * vertex position\n */\nvec4 getVertexPosition()\n{\n    vec4 position = a_Position;\n\n    #ifdef MORPHTARGETS\n\t#ifdef MORPHTARGETS_POSITION\n    #ifdef GRAPHICS_API_GLES3\n    position.xyz = positionMorph(position.xyz);\n    #endif // GRAPHICS_API_GLES3\n\t#endif // MORPHTARGETS_POSITION\n    #endif // MORPHTARGETS\n\n    return position;\n}\n\nvec3 getVertexNormal()\n{\n    vec3 normal = a_Normal.xyz;\n    #ifdef MORPHTARGETS\n\t#ifdef MORPHTARGETS_NORMAL\n    #ifdef GRAPHICS_API_GLES3\n    normal.xyz = normalMorph(normal);\n    #endif // GRAPHICS_API_GLES3\n\t#endif // MORPHTARGETS_NORMAL\n    #endif // MORPHTARGETS\n\n    return normal;\n}\n\n    #ifdef TANGENT\nvec4 getVertexTangent()\n{\n    vec4 tangent = a_Tangent0;\n\n\t#ifdef MORPHTARGETS\n\t#ifdef MORPHTARGETS_TANGENT\n    #ifdef GRAPHICS_API_GLES3\n    tangent = tangentMorph(tangent);\n    #endif // GRAPHICS_API_GLES3\n\t#endif // MORPHTARGETS_TANGENT\n\t#endif // MORPHTARGETS\n\n    return tangent;\n}\n    #endif // TANGENT\n\n    #ifdef LIGHTMAP\n#ifndef GPU_INSTANCE\n    uniform vec4 u_LightmapScaleOffset;\n#endif // GPU_INSTANCE\n\nvec4 getLightmapScaleOffset(){\n    \n    #ifdef GPU_INSTANCE\n        return a_LightmapScaleOffset;\n    #else\n        return u_LightmapScaleOffset;\n    #endif // GPU_INSTANCE\n}\n    #endif // LIGHTMAP\n\nvoid getVertexParams(inout Vertex vertex)\n{\n    vertex.positionOS = getVertexPosition().xyz;\n\n    vertex.normalOS = getVertexNormal();\n\n    #ifdef TANGENT\n    vertex.tangentOS = getVertexTangent();\n    #endif // TANGENT\n\n    #ifdef UV\n    vertex.texCoord0 = a_Texcoord0;\n    #endif // UV\n\n    #ifdef UV1\n    vertex.texCoord1 = a_Texcoord1;\n    #endif // UV1\n\n    #ifdef COLOR\n    // consider vertexColor is gamma\n    vertex.vertexColor = vec4(pow(a_Color.rgb, vec3(2.2)), a_Color.a);\n    #endif // COLOR\n\n    #ifdef LIGHTMAP\n    vertex.lightmapScaleOffset = getLightmapScaleOffset();\n\t#endif LIGHTMAP\n}\n\n#endif // VertexCommon_lib";

    var ShadingCommonGLSL = "#if !defined(ShadingCommon_lib)\n    #define ShadingCommon_lib\n\n// varying\nvarying vec3 v_PositionWS;\n// todo\nvarying vec3 v_NormalWS;\nvarying vec3 v_TangentWS;\nvarying vec3 v_BiNormalWS;\n\n    #ifdef UV\nvarying vec2 v_Texcoord0;\n    #endif // UV\n\n    #ifdef UV1\n\t#ifdef LIGHTMAP\nvarying vec2 v_Texcoord1;\n\t#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\nvarying vec4 v_VertexColor;\n    #endif // COLOR\n\n// 记录顶点信息, 用于由vs向fs传递数据\nstruct PixelParams {\n    vec3 positionWS;\n\n    // todo\n    vec3 normalWS;\n    vec3 tangentWS;\n    vec3 biNormalWS;\n    mat3 TBN;\n\n    #ifdef UV\n    vec2 uv0;\n    #endif // UV\n\n    #ifdef UV1\n\t#ifdef LIGHTMAP\n    vec2 uv1;\n\t#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\n    vec4 vertexColor;\n    #endif // COLOR\n};\n\n#endif // ShadingCommon_lib";

    var ShadingVertexGLSL = "#if !defined(ShadingVertex_lib)\n    #define ShadingVertex_lib\n\n    #include \"ShadingCommon.glsl\";\n\nvoid sharePixelParams(const in PixelParams params)\n{\n    v_PositionWS = params.positionWS;\n\n    v_NormalWS = params.normalWS;\n    v_TangentWS = params.tangentWS;\n    v_BiNormalWS = params.biNormalWS;\n\n    #ifdef UV\n    v_Texcoord0 = params.uv0;\n    #endif // UV\n\n    #ifdef UV1\n\t#ifdef LIGHTMAP\n    v_Texcoord1 = params.uv1;\n\t#endif LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\n    v_VertexColor = params.vertexColor;\n    #endif // COLOR\n}\n\nvoid shadingPixelParams(inout PixelParams params, in Vertex vertex)\n{\n    mat4 worldMat = getWorldMatrix();\n    vec4 pos = (worldMat * vec4(vertex.positionOS, 1.0));\n    params.positionWS = pos.xyz / pos.w;\n\n    mat3 normalMat = transpose(inverse(mat3(worldMat)));\n    params.normalWS = normalize((normalMat * vertex.normalOS).xyz);\n\n    #ifdef TANGENT\n    params.tangentWS = normalize((normalMat * vertex.tangentOS.xyz).xyz);\n    params.tangentWS *= u_WroldInvertFront.x;\n    params.biNormalWS = normalize(cross(params.normalWS, params.tangentWS) * sign(vertex.tangentOS.w));\n    #else // TANGENT\n    params.tangentWS = vec3(1.0, 0.0, 0.0);\n    params.tangentWS *= u_WroldInvertFront.x;\n    params.biNormalWS = normalize(cross(params.normalWS, params.tangentWS));\n    #endif // TANGENT\n\n    #ifdef UV\n    params.uv0 = vertex.texCoord0;\n    #endif // UV\n\n    #ifdef UV1\n\t#ifdef LIGHTMAP\n    params.uv1 = tranformLightMapUV(vertex.texCoord1, vertex.lightmapScaleOffset);\n\t#endif LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\n    params.vertexColor = vertex.vertexColor;\n    #endif // COLOR\n}\n\n#endif // ShadingVertex_lib";

    var ShadingFragGLSL = "#if !defined(ShadingFrag_lib)\n    #define ShadingFrag_lib\n\n    #include \"ShadingCommon.glsl\";\n\n    #define _InvertNormal (float(gl_FrontFacing) * 2.0 - 1.0);\n\nvoid getPixelParams(inout PixelParams params)\n{\n    params.positionWS = v_PositionWS;\n\n    float invertN = _InvertNormal;\n\n    params.normalWS = normalize(v_NormalWS * invertN);\n    params.tangentWS = normalize(v_TangentWS * invertN);\n    params.biNormalWS = normalize(v_BiNormalWS * invertN);\n\n    params.TBN = mat3(params.tangentWS, params.biNormalWS, params.normalWS);\n\n    #ifdef UV\n    params.uv0 = v_Texcoord0;\n    #endif // UV\n\n    #ifdef UV1\n\t#ifdef LIGHTMAP\n    params.uv1 = v_Texcoord1;\n\t#endif // LIGHTMAP\n    #endif // UV1\n\n    #ifdef COLOR\n    params.vertexColor = v_VertexColor;\n    #endif // COLOR\n}\n\n#endif // ShadingFrag_lib";

    var SceneGLSL = "#if !defined(SceneCommon_lib)\n    #define SceneCommon_lib\n\n    #ifdef ENUNIFORMBLOCK\nuniform SceneUniformBlock\n{\n    // time\n    float u_Time;\n    vec4 u_FogParams;// x start,y range,z Density\n    vec4 u_FogColor;\n};\n    #else // ENUNIFORMBLOCK\n// time\nuniform float u_Time;\nuniform vec4 u_FogParams;//x start,y range,z Density\nuniform vec4 u_FogColor;\n    #endif // ENUNIFORMBLOCK\n    //rotate SH IBL\nuniform float u_GIRotate;\n\n#endif // SceneCommon_lib";

    var CameraGLSL = "#if !defined(CameraCommon_lib)\n    #define CameraCommon_lib\n\n    #ifdef ENUNIFORMBLOCK\n\nuniform CameraUniformBlock\n{\n    mat4 u_View;\n    mat4 u_Projection;\n    mat4 u_ViewProjection;\n    vec4 u_ProjectionParams; // x: near, y: far, z: invert, w: 1/far\n    vec4 u_Viewport; // x,y,width,height\n    vec3 u_CameraDirection;\n    vec3 u_CameraUp;\n    vec3 u_CameraPos;\n};\n    #else\nuniform mat4 u_View;\nuniform mat4 u_Projection;\nuniform mat4 u_ViewProjection;\nuniform vec4 u_ProjectionParams; // x: near, y: far, z: invert, w: 1/far\nuniform vec4 u_Viewport; // x, y, width, height\nuniform vec3 u_CameraDirection;\nuniform vec3 u_CameraUp;\nuniform vec3 u_CameraPos;\n    #endif // ENUNIFORMBLOCK\n\n/*Depth or DepthNormal Uniform*/\nuniform highp sampler2D u_CameraDepthTexture;\nuniform vec4 u_ZBufferParams; //(1.0 - far / near, far / near, (near - far) / (near * far), 1 / near)\nuniform mediump sampler2D u_CameraDepthNormalsTexture;\nuniform mediump sampler2D u_CameraOpaqueTexture;\nuniform vec4 u_OpaqueTextureParams;\n\nvec4 getPositionCS(in vec3 positionWS)\n{\n    return u_ViewProjection * vec4(positionWS, 1.0);\n}\n\nvec3 getViewDirection(in vec3 positionWS)\n{\n    return normalize(u_CameraPos - positionWS);\n}\n\n// 根据投影矩阵重映射深度\nvec4 remapPositionZ(vec4 position)\n{\n    #ifdef BLITSCREEN_INVERTY\n    position.y = -position.y;\n    #endif\n\n    #ifdef REMAP_Z\n    position.z = position.z * 2.0 - position.w;\n    #endif\n    return position;\n}\n\n#endif // CameraCommon_lib";

    var SkyCommon = "#if !defined(SkyCommon_lib)\n    #define SkyCommon_lib\n\nuniform vec3 u_SunLight_direction;\nuniform vec4 u_SunLight_color;\nuniform mat4 u_SkyViewMat;\nuniform mat4 u_SkyProjectionMat;\nuniform mat4 u_SkyProjectionViewMat;\n\nvec4 remapSkyPositionZ(in vec4 position)\n{\n    position.z = position.w;\n    #ifdef BLITSCREEN_INVERTY\n    position.y = -position.y;\n    #endif\n    return position;\n}\n\nconst float c_deg2ang = 3.141593 / 180.0;\nvec4 rotateAroundYInDegrees(vec4 vertex, float deg)\n{\n    float angle = deg * c_deg2ang;\n    float sina = sin(angle);\n    float cosa = cos(angle);\n    mat2 m = mat2(cosa, -sina, sina, cosa);\n    return vec4(m * vertex.xz, vertex.yw).xzyw;\n}\n\n\n#endif // SkyCommon_lib";

    var Sprite3DCommonGLSL = "#if !defined(Sprite3DCommon_lib)\n    #define Sprite3DCommon_lib\n\nuniform mat4 u_WorldMat;\n\nuniform vec4 u_WroldInvertFront; // x: invert front face\n\n    \n\n\nvec2 tranformLightMapUV(in vec2 texcoord, in vec4 tilingOffset)\n{\n    vec2 lightMapUV = vec2(texcoord.x, 1.0 - texcoord.y) * tilingOffset.xy + tilingOffset.zw;\n    lightMapUV.y = 1.0 - lightMapUV.y;\n    return lightMapUV;\n}\n\nvec2 transformUV(in vec2 texcoord, in vec4 tilingOffset)\n{\n    vec2 uv = texcoord * tilingOffset.xy + tilingOffset.zw * vec2(1.0, -1.0) + vec2(0.0, 1.0 - tilingOffset.y);\n    return uv;\n}\n\n#endif // Sprite3DCommon_lib";

    var Sprite3DVertexGLSL = "#if !defined(Sprite3DVertex_lib)\n    #define Sprite3DVertex_lib\n\n    #include \"Sprite3DCommon.glsl\";\n\n    #ifdef BONE\n// todo const int c_MaxBoneCount = 24\nuniform mat4 u_Bones[24];\n\n\t#ifdef SIMPLEBONE\nuniform vec4 u_SimpleAnimatorParams;\nuniform sampler2D u_SimpleAnimatorTexture;\nuniform float u_SimpleAnimatorTextureSize;\n\t    #include \"BakedBoneMatrixSampler.glsl\";\n\n\t#endif // SIMPLEBONE\n\n    #endif // BONE\n\n/**\n * world matrix\n */\nmat4 getWorldMatrix()\n{\n    #ifdef GPU_INSTANCE\n    mat4 worldMat = a_WorldMat;\n    #else\n    mat4 worldMat = u_WorldMat;\n    #endif // GPU_INSTANCE\n\n    #ifdef BONE\n\n\t#ifdef SIMPLEBONE\n\n\t    #ifdef GPU_INSTANCE\n    float currentPixelPos = a_SimpleTextureParams.x + a_SimpleTextureParams.y;\n\t    #else // GPU_INSTANCE\n    float currentPixelPos = u_SimpleAnimatorParams.x + u_SimpleAnimatorParams.y;\n\t    #endif // GPU_INSTANCE\n\n    float offset = 1.0 / u_SimpleAnimatorTextureSize;\n    mat4 skinTrans = loadBakedMatMatrix(currentPixelPos, a_BoneIndices.x, offset) * a_BoneWeights.x;\n    skinTrans += loadBakedMatMatrix(currentPixelPos, a_BoneIndices.y, offset) * a_BoneWeights.y;\n    skinTrans += loadBakedMatMatrix(currentPixelPos, a_BoneIndices.z, offset) * a_BoneWeights.z;\n    skinTrans += loadBakedMatMatrix(currentPixelPos, a_BoneIndices.w, offset) * a_BoneWeights.w;\n    worldMat = worldMat * skinTrans;\n\n\t#else // SIMPLEBONE\n\n    ivec4 boneIndex = ivec4(a_BoneIndices);\n    mat4 skinTrans = u_Bones[boneIndex.x] * a_BoneWeights.x;\n    skinTrans += u_Bones[boneIndex.y] * a_BoneWeights.y;\n    skinTrans += u_Bones[boneIndex.z] * a_BoneWeights.z;\n    skinTrans += u_Bones[boneIndex.w] * a_BoneWeights.w;\n    worldMat = worldMat * skinTrans;\n\n\t#endif // SIMPLEBONE\n\n    #endif // BONE\n\n    return worldMat;\n}\n\nvec2 getSimpleBoneCustomData(){\n    vec2 custom;\n   #ifdef BONE\n    #ifdef SIMPLEBONE\n    #ifdef GPU_INSTANCE\n    custom=a_SimpleTextureParams.zw;\n    #else// GPU_INSTANCE\n    custom=u_SimpleAnimatorParams.zw;\n    #endif// GPU_INSTANCE\n    #endif// SIMPLEBONE\n  #endif // BONE\n    return custom;\n}\n\n#endif // Sprite3DVertex_lib";

    var Sprite3DFragGLSL = "#if !defined(Sprite3DFrag_lib)\n    #define Sprite3DFrag_lib\n\n    #include \"Sprite3DCommon.glsl\";\n\n#endif // Sprite3DFrag_lib";

    var DepthVertexGLSL = "#if !defined(DepthVertex_lib)\n    #define DepthVertex_lib\n    #include \"Math.glsl\";\n    #include \"Scene.glsl\";\n    #include \"Camera.glsl\";\n    #include \"Sprite3DVertex.glsl\";\n\n    #include \"VertexCommon.glsl\";\n\n    #if defined(SHADOW) || defined(SHADOW_SPOT)\n\n\t#ifndef DEPTHPASS\n\t    #ifdef ENUNIFORMBLOCK\nuniform ShadowUniformBlock\n{\n    vec4 u_ShadowBias; // x: depth bias, y: normal bias\n    vec3 u_ShadowLightDirection;\n};\n\t    #else // ENUNIFORMBLOCK\nuniform vec4 u_ShadowBias; // x: depth bias, y: normal bias\n\t\t#ifdef SHADOW\nuniform vec3 u_ShadowLightDirection;\n\t\t#endif // SHADOW\n\t    #endif // ENUNIFORMBLOCK\n\nvec3 applyShadowBias(vec3 positionWS, vec3 normalWS, vec3 lightDirection)\n{\n    float invNdotL = 1.0 - clamp(dot(-lightDirection, normalWS), 0.0, 1.0);\n    float scale = invNdotL * u_ShadowBias.y;\n\n    // normal bias is negative since we want to apply an inset normal offset\n    positionWS += -lightDirection * u_ShadowBias.xxx;\n    positionWS += normalWS * vec3(scale);\n    return positionWS;\n}\n\t#endif // DEPTHPASS\n    #endif // SHADOW || SHADOW_SPOT\n\n    #ifdef DEPTHPASS\n\t#include \"Camera.glsl\";\n    #endif // DEPTHPASS\n\nvec4 DepthPositionCS(in vec3 positionWS, in vec3 normalWS)\n{\n    #ifdef DEPTHPASS\n    vec4 positionCS = u_ViewProjection * vec4(positionWS, 1.0);\n    #endif // DEPTHPASS\n\n    #ifdef SHADOW\n\t#ifndef DEPTHPASS\n    positionWS = applyShadowBias(positionWS, normalWS, u_ShadowLightDirection);\n    vec4 positionCS = u_ViewProjection * vec4(positionWS, 1.0);\n    positionCS.z = max(positionCS.z, 0.0); // min ndc z is 0.0\n\t#endif // DEPTHPASS\n    #endif // SHADOW\n\n    #ifdef SHADOW_SPOT\n\t#ifndef DEPTHPASS\n    vec4 positionCS = u_ViewProjection * vec4(positionWS, 1.0);\n    positionCS.z = positionCS.z - u_ShadowBias.x / positionCS.w;\n    positionCS.z = max(positionCS.z, 0.0); // min ndc z is 0.0\n\t#endif // DEPTHPASS\n    #endif // SHADOW_SPOT\n\n    return positionCS;\n}\n\n#endif // DepthVertex_lib";

    var DepthFragGLSL = "#if !defined(DepthFrag_lib)\n    #define DepthFrag_lib\n\nvec4 getDepthColor()\n{\n    return vec4(0.0);\n}\n\n#endif // DepthFrag_lib";

    var DepthNormalUtilGLSL = "#define SAMPLE_DEPTH_TEXTURE(textureName, coord2) (texture2D(textureName, coord2).r)\n//此方法库用来压缩解析深度贴图，法线深度贴图\n\n// Encoding/decoding view space normals into 2D 0..1 vector\nvec2 EncodeViewNormalStereo(vec3 n)\n{\n    n.z = abs(n.z);\n    float kScale = 1.7777;\n    vec2 enc;\n    enc = n.xy / (n.z + 1.0);\n    enc /= kScale;\n    enc = enc * 0.5 + 0.5;\n    return enc;\n}\n\nvec3 DecodeViewNormalStereo(vec4 enc4)\n{\n    float kScale = 1.7777;\n    vec3 nn = enc4.xyz * vec3(2.0 * kScale, 2.0 * kScale, 0.0) + vec3(-kScale, -kScale, 1.0);\n    float g = 2.0 / dot(nn.xyz, nn.xyz);\n    vec3 n;\n    n.xy = g * nn.xy;\n    n.z = g - 1.0;\n    return n;\n}\n\n// Encoding/decoding [0..1) floats into 8 bit/channel RG. Note that 1.0 will not be encoded properly.\nvec2 EncodeFloatRG(float v)\n{\n    vec2 kEncodeMul = vec2(1.0, 255.0);\n    float kEncodeBit = 1.0 / 255.0;\n    vec2 enc = kEncodeMul * v;\n    enc = fract(enc);\n    enc.x -= enc.y * kEncodeBit;\n    return enc;\n}\n\nfloat DecodeFloatRG(vec2 enc)\n{\n    vec2 kDecodeDot = vec2(1.0, 1.0 / 255.0);\n    return dot(enc, kDecodeDot);\n}\n\nvec4 EncodeDepthNormal(float depth, vec3 normals)\n{\n    vec4 encode;\n    encode.xy = EncodeViewNormalStereo(normals);\n    encode.zw = EncodeFloatRG(depth);\n    return encode;\n}\n\nvoid DecodeDepthNormal(vec4 enc, out float depth, out vec3 normal)\n{\n    depth = DecodeFloatRG(enc.zw);\n    normal = DecodeViewNormalStereo(enc);\n}\n\nvec4 depthNormalsFragment(vec4 depthNormal)\n{\n    return EncodeDepthNormal(depthNormal.w, depthNormal.xyz);\n}\n\n// Z buffer to linear 0..1 depth\nfloat Linear01Depth(float z, vec4 zbufferParams)\n{\n    return 1.0 / (zbufferParams.x * z + zbufferParams.y);\n}\n// Z buffer to linear depth\nfloat LinearEyeDepth(float z, vec4 zbufferParams)\n{\n    return 1.0 / (zbufferParams.z * z + zbufferParams.w);\n}\n";

    var DepthNormalFragGLSL = "#if !defined(DepthNormalFrag_lib)\n    #define DepthNormalFrag_lib\n\n    #include \"DepthNormalUtil.glsl\";\n\nvec4 encodeDepthNormal(const in vec4 positionCS, const in vec3 normalWS)\n{\n    float depth = (positionCS.z * 2.0 - positionCS.w) * u_ProjectionParams.w;\n\n    vec3 normalVS = mat3(u_View) * normalWS;\n\n    return EncodeDepthNormal(depth, normalVS);\n}\n\n#endif // DepthNormalFrag_lib";

    var ShadowSampleTentGLSL = "// ------------------------------------------------------------------\n//  PCF Filtering Tent Functions\n// ------------------------------------------------------------------\n\n// Assuming a isoceles right angled triangle of height \"triangleHeight\" (as drawn below).\n// This function return the area of the triangle above the first texel(in Y the first texel).\n//\n// |\\      <-- 45 degree slop isosceles right angled triangle\n// | \\\n// ----    <-- length of this side is \"triangleHeight\"\n// _ _ _ _ <-- texels\nfloat sampleShadowGetIRTriangleTexelArea(float triangleHeight)\n{\n    return triangleHeight - 0.5;\n}\n\n// Assuming a isoceles triangle of 1.5 texels height and 3 texels wide lying on 4 texels.\n// This function return the area of the triangle above each of those texels.\n//    |    <-- offset from -0.5 to 0.5, 0 meaning triangle is exactly in the center\n//   / \\   <-- 45 degree slop isosceles triangle (ie tent projected in 2D)\n//  /   \\\n// _ _ _ _ <-- texels\n// X Y Z W <-- result indices (in computedArea.xyzw and computedAreaUncut.xyzw)\n// Top point at (right,top) in a texel,left bottom point at (middle,middle) in a texel,right bottom point at (middle,middle) in a texel.\nvoid sampleShadowGetTexelAreasTent3x3(float offset, out vec4 computedArea, out vec4 computedAreaUncut)\n{\n    // Compute the exterior areas,a and h is same.\n    float a = offset + 0.5;\n    float offsetSquaredHalved = a * a * 0.5;\n    computedAreaUncut.x = computedArea.x = offsetSquaredHalved - offset;\n    computedAreaUncut.w = computedArea.w = offsetSquaredHalved;\n\n    // Compute the middle areas\n    // For Y : We find the area in Y of as if the left section of the isoceles triangle would\n    // intersect the axis between Y and Z (ie where offset = 0).\n    computedAreaUncut.y = sampleShadowGetIRTriangleTexelArea(1.5 - offset);\n    // This area is superior to the one we are looking for if (offset < 0) thus we need to\n    // subtract the area of the triangle defined by (0,1.5-offset), (0,1.5+offset), (-offset,1.5).\n    float clampedOffsetLeft = min(offset,0.0);\n    float areaOfSmallLeftTriangle = clampedOffsetLeft * clampedOffsetLeft;\n    computedArea.y = computedAreaUncut.y - areaOfSmallLeftTriangle;\n\n    // We do the same for the Z but with the right part of the isoceles triangle\n    computedAreaUncut.z = sampleShadowGetIRTriangleTexelArea(1.5 + offset);\n    float clampedOffsetRight = max(offset,0.0);\n    float areaOfSmallRightTriangle = clampedOffsetRight * clampedOffsetRight;\n    computedArea.z = computedAreaUncut.z - areaOfSmallRightTriangle;\n}\n\n// Assuming a isoceles triangle of 2.5 texel height and 5 texels wide lying on 6 texels.\n// This function return the weight of each texels area relative to the full triangle area.\n//  /       \\\n// _ _ _ _ _ _ <-- texels\n// 0 1 2 3 4 5 <-- computed area indices (in texelsWeights[])\n// Top point at (right,top) in a texel,left bottom point at (middle,middle) in a texel,right bottom point at (middle,middle) in a texel.\nvoid sampleShadowGetTexelWeightsTent5x5(float offset, out vec3 texelsWeightsA, out vec3 texelsWeightsB)\n{\n    vec4 areaFrom3texelTriangle;\n    vec4 areaUncutFrom3texelTriangle;\n    sampleShadowGetTexelAreasTent3x3(offset, areaFrom3texelTriangle, areaUncutFrom3texelTriangle);\n\n    // Triangle slope is 45 degree thus we can almost reuse the result of the 3 texel wide computation.\n    // the 5 texel wide triangle can be seen as the 3 texel wide one but shifted up by one unit/texel.\n    // 0.16 is 1/(the triangle area)\n    texelsWeightsA.x = 0.16 * (areaFrom3texelTriangle.x);\n    texelsWeightsA.y = 0.16 * (areaUncutFrom3texelTriangle.y);\n    texelsWeightsA.z = 0.16 * (areaFrom3texelTriangle.y + 1.0);\n    texelsWeightsB.x = 0.16 * (areaFrom3texelTriangle.z + 1.0);\n    texelsWeightsB.y = 0.16 * (areaUncutFrom3texelTriangle.z);\n    texelsWeightsB.z = 0.16 * (areaFrom3texelTriangle.w);\n}\n\n// 5x5 Tent filter (45 degree sloped triangles in U and V)\nvoid sampleShadowComputeSamplesTent5x5(vec4 shadowMapTextureTexelSize, vec2 coord, out float fetchesWeights[9], out vec2 fetchesUV[9])\n{\n    // tent base is 5x5 base thus covering from 25 to 36 texels, thus we need 9 bilinear PCF fetches\n    vec2 tentCenterInTexelSpace = coord.xy * shadowMapTextureTexelSize.zw;\n    vec2 centerOfFetchesInTexelSpace = floor(tentCenterInTexelSpace + 0.5);\n    vec2 offsetFromTentCenterToCenterOfFetches = tentCenterInTexelSpace - centerOfFetchesInTexelSpace;\n\n    // find the weight of each texel based on the area of a 45 degree slop tent above each of them.\n    vec3 texelsWeightsUA, texelsWeightsUB;\n    vec3 texelsWeightsVA, texelsWeightsVB;\n    sampleShadowGetTexelWeightsTent5x5(offsetFromTentCenterToCenterOfFetches.x, texelsWeightsUA, texelsWeightsUB);\n    sampleShadowGetTexelWeightsTent5x5(offsetFromTentCenterToCenterOfFetches.y, texelsWeightsVA, texelsWeightsVB);\n\n    // each fetch will cover a group of 2x2 texels, the weight of each group is the sum of the weights of the texels\n    vec3 fetchesWeightsU = vec3(texelsWeightsUA.xz, texelsWeightsUB.y) + vec3(texelsWeightsUA.y, texelsWeightsUB.xz);\n    vec3 fetchesWeightsV = vec3(texelsWeightsVA.xz, texelsWeightsVB.y) + vec3(texelsWeightsVA.y, texelsWeightsVB.xz);\n\n    // move the PCF bilinear fetches to respect texels weights\n    vec3 fetchesOffsetsU = vec3(texelsWeightsUA.y, texelsWeightsUB.xz) / fetchesWeightsU.xyz + vec3(-2.5,-0.5,1.5);\n    vec3 fetchesOffsetsV = vec3(texelsWeightsVA.y, texelsWeightsVB.xz) / fetchesWeightsV.xyz + vec3(-2.5,-0.5,1.5);\n    fetchesOffsetsU *= shadowMapTextureTexelSize.xxx;\n    fetchesOffsetsV *= shadowMapTextureTexelSize.yyy;\n\n    vec2 bilinearFetchOrigin = centerOfFetchesInTexelSpace * shadowMapTextureTexelSize.xy;\n    fetchesUV[0] = bilinearFetchOrigin + vec2(fetchesOffsetsU.x, fetchesOffsetsV.x);\n    fetchesUV[1] = bilinearFetchOrigin + vec2(fetchesOffsetsU.y, fetchesOffsetsV.x);\n    fetchesUV[2] = bilinearFetchOrigin + vec2(fetchesOffsetsU.z, fetchesOffsetsV.x);\n    fetchesUV[3] = bilinearFetchOrigin + vec2(fetchesOffsetsU.x, fetchesOffsetsV.y);\n    fetchesUV[4] = bilinearFetchOrigin + vec2(fetchesOffsetsU.y, fetchesOffsetsV.y);\n    fetchesUV[5] = bilinearFetchOrigin + vec2(fetchesOffsetsU.z, fetchesOffsetsV.y);\n    fetchesUV[6] = bilinearFetchOrigin + vec2(fetchesOffsetsU.x, fetchesOffsetsV.z);\n    fetchesUV[7] = bilinearFetchOrigin + vec2(fetchesOffsetsU.y, fetchesOffsetsV.z);\n    fetchesUV[8] = bilinearFetchOrigin + vec2(fetchesOffsetsU.z, fetchesOffsetsV.z);\n\n    fetchesWeights[0] = fetchesWeightsU.x * fetchesWeightsV.x;\n    fetchesWeights[1] = fetchesWeightsU.y * fetchesWeightsV.x;\n    fetchesWeights[2] = fetchesWeightsU.z * fetchesWeightsV.x;\n    fetchesWeights[3] = fetchesWeightsU.x * fetchesWeightsV.y;\n    fetchesWeights[4] = fetchesWeightsU.y * fetchesWeightsV.y;\n    fetchesWeights[5] = fetchesWeightsU.z * fetchesWeightsV.y;\n    fetchesWeights[6] = fetchesWeightsU.x * fetchesWeightsV.z;\n    fetchesWeights[7] = fetchesWeightsU.y * fetchesWeightsV.z;\n    fetchesWeights[8] = fetchesWeightsU.z * fetchesWeightsV.z;\n}";

    var ShadowSamplerGLSL = "//兼容WGSL\n#if !defined(ShadowSampler_lib)\n    #define ShadowSampler_lib\n\n    #ifndef GRAPHICS_API_GLES3\n\t#define NO_NATIVE_SHADOWMAP\n    #endif // GRAPHICS_API_GLES3\n\n    #if defined(NO_NATIVE_SHADOWMAP)\n\t#define TEXTURE2D_SHADOW(textureName)\t\t     uniform mediump sampler2D textureName\n    #define SAMPLE_TEXTURE2D_SHADOW(textureName, coord3) (texture2D(textureName, coord3.xy).r < coord3.z ? 0.0 : 1.0)\n\t#define TEXTURE2D_SHADOW_PARAM(shadowMap)\t     mediump sampler2D shadowMap\n    #else // NO_NATIVE_SHADOWMAP\n\t#define TEXTURE2D_SHADOW(textureName)\t\t     uniform mediump sampler2DShadow textureName\n\t#define SAMPLE_TEXTURE2D_SHADOW(textureName, coord3) textureLod(textureName, coord3, 0.0)\n\t#define TEXTURE2D_SHADOW_PARAM(shadowMap)\t     mediump sampler2DShadow shadowMap\n    #endif // NO_NATIVE_SHADOWMAP\n\n    // 计算阴影\n    #ifdef RECEIVESHADOW\n\n\t#include \"ShadowSampleTent.glsl\";\n\nuniform vec4 u_ShadowParams;\n\n\t#define ShadowStrength\t   u_ShadowParams.x\n\t#define SpotShadowStrength u_ShadowParams.y\n\n    // 平行光阴影\n\t#ifdef SHADOW\n\t    #define CALCULATE_SHADOWS\nvarying vec4 v_ShadowCoord;\nTEXTURE2D_SHADOW(u_ShadowMap);\nuniform vec4 u_ShadowMapSize;\n\n// #ifdef SHADOW_CASCADE\n// const int c_MaxCascadeCount = 4;\n// #else //SHADOW_CASCADE\n// const int c_MaxCascadeCount = 1;\n// #endif//SHADOW_CASCADE\n// uniform mat4 u_ShadowMatrices[c_MaxCascadeCount];\n// uniform vec4 u_ShadowSplitSpheres[c_MaxCascadeCount];\n\nuniform mat4 u_ShadowMatrices[4];\nuniform vec4 u_ShadowSplitSpheres[4];\n\t#endif // SHADOW\n\n\t// 聚光灯阴影\n\t#ifdef SHADOW_SPOT\n\t    #define CALCULATE_SPOTSHADOWS\nvarying vec4 v_SpotShadowCoord;\nTEXTURE2D_SHADOW(u_SpotShadowMap);\nuniform vec4 u_SpotShadowMapSize;\nuniform mat4 u_SpotViewProjectMatrix;\n\t#endif // SHADOW_SPOT\n\nfloat sampleShdowMapFiltered4(TEXTURE2D_SHADOW_PARAM(shadowMap), vec3 shadowCoord, vec4 shadowMapSize)\n{\n    float attenuation;\n    vec4 attenuation4;\n    vec2 offset = shadowMapSize.xy / 2.0;\n    vec3 shadowCoord0 = shadowCoord + vec3(-offset, 0.0);\n    vec3 shadowCoord1 = shadowCoord + vec3(offset.x, -offset.y, 0.0);\n    vec3 shadowCoord2 = shadowCoord + vec3(-offset.x, offset.y, 0.0);\n    vec3 shadowCoord3 = shadowCoord + vec3(offset, 0.0);\n    attenuation4.x = SAMPLE_TEXTURE2D_SHADOW(shadowMap, shadowCoord0);\n    attenuation4.y = SAMPLE_TEXTURE2D_SHADOW(shadowMap, shadowCoord1);\n    attenuation4.z = SAMPLE_TEXTURE2D_SHADOW(shadowMap, shadowCoord2);\n    attenuation4.w = SAMPLE_TEXTURE2D_SHADOW(shadowMap, shadowCoord3);\n    attenuation = dot(attenuation4, vec4(0.25));\n    return attenuation;\n}\n\nfloat sampleShdowMapFiltered9(TEXTURE2D_SHADOW_PARAM(shadowMap), vec3 shadowCoord, vec4 shadowmapSize)\n{\n    float attenuation;\n    float fetchesWeights[9];\n    vec2 fetchesUV[9];\n    sampleShadowComputeSamplesTent5x5(shadowmapSize, shadowCoord.xy, fetchesWeights, fetchesUV);\n    attenuation = fetchesWeights[0] * SAMPLE_TEXTURE2D_SHADOW(shadowMap, vec3(fetchesUV[0].xy, shadowCoord.z));\n    attenuation += fetchesWeights[1] * SAMPLE_TEXTURE2D_SHADOW(shadowMap, vec3(fetchesUV[1].xy, shadowCoord.z));\n    attenuation += fetchesWeights[2] * SAMPLE_TEXTURE2D_SHADOW(shadowMap, vec3(fetchesUV[2].xy, shadowCoord.z));\n    attenuation += fetchesWeights[3] * SAMPLE_TEXTURE2D_SHADOW(shadowMap, vec3(fetchesUV[3].xy, shadowCoord.z));\n    attenuation += fetchesWeights[4] * SAMPLE_TEXTURE2D_SHADOW(shadowMap, vec3(fetchesUV[4].xy, shadowCoord.z));\n    attenuation += fetchesWeights[5] * SAMPLE_TEXTURE2D_SHADOW(shadowMap, vec3(fetchesUV[5].xy, shadowCoord.z));\n    attenuation += fetchesWeights[6] * SAMPLE_TEXTURE2D_SHADOW(shadowMap, vec3(fetchesUV[6].xy, shadowCoord.z));\n    attenuation += fetchesWeights[7] * SAMPLE_TEXTURE2D_SHADOW(shadowMap, vec3(fetchesUV[7].xy, shadowCoord.z));\n    attenuation += fetchesWeights[8] * SAMPLE_TEXTURE2D_SHADOW(shadowMap, vec3(fetchesUV[8].xy, shadowCoord.z));\n    return attenuation;\n}\n    #endif // RECEIVESHADOW\n\n    // 计算平行光阴影\n    #if defined(CALCULATE_SHADOWS)\n\n#ifdef SHADOW_CASCADE\n// 平行光阴影级联索引\nmediump int computeCascadeIndex(in vec3 positionWS)\n{\n    vec3 fromCenter0 = positionWS - u_ShadowSplitSpheres[0].xyz;\n    vec3 fromCenter1 = positionWS - u_ShadowSplitSpheres[1].xyz;\n    vec3 fromCenter2 = positionWS - u_ShadowSplitSpheres[2].xyz;\n    vec3 fromCenter3 = positionWS - u_ShadowSplitSpheres[3].xyz;\n\n    mediump vec4 comparison = vec4(dot(fromCenter0, fromCenter0) < u_ShadowSplitSpheres[0].w,\n\tdot(fromCenter1, fromCenter1) < u_ShadowSplitSpheres[1].w,\n\tdot(fromCenter2, fromCenter2) < u_ShadowSplitSpheres[2].w,\n\tdot(fromCenter3, fromCenter3) < u_ShadowSplitSpheres[3].w);\n\n    comparison.yzw = clamp(comparison.yzw - comparison.xyz, 0.0, 1.0); // keep the nearest\n    mediump vec4 indexCoefficient = vec4(4.0, 3.0, 2.0, 1.0);\n    mediump int index = 4 - int(dot(comparison, indexCoefficient));\n    return index;\n}\n#endif\n\n// 平行光阴影坐标\nvec4 getShadowCoord(in vec3 positionWS)\n{\n\t#ifdef SHADOW_CASCADE\n    mediump int cascadeIndex = computeCascadeIndex(positionWS);\n\t    #ifdef GRAPHICS_API_GLES3\n    mat4 shadowMat = u_ShadowMatrices[cascadeIndex];\n\t    #else // GRAPHICS_API_GLES3\n    mat4 shadowMat;\n    if (cascadeIndex == 0)\n\t{\n\t    shadowMat = u_ShadowMatrices[0];\n\t}\n    else if (cascadeIndex == 1)\n\t{\n\t    shadowMat = u_ShadowMatrices[1];\n\t}\n    else if (cascadeIndex == 2)\n\t{\n\t    shadowMat = u_ShadowMatrices[2];\n\t}\n    else\n\t{\n\t    shadowMat = u_ShadowMatrices[3];\n\t}\n\t    #endif // GRAPHICS_API_GLES3\n\n    return shadowMat * vec4(positionWS, 1.0);\n\n\t#else // SHADOW_CASCADE\n\n    return u_ShadowMatrices[0] * vec4(positionWS, 1.0);\n\n\t#endif // SHADOW_CASCADE\n}\n\n// 采样平行光阴影\nfloat sampleShadowmap(in vec4 shadowCoord)\n{\n    float attenuation = 1.0;\n\n    vec3 coord = shadowCoord.xyz / shadowCoord.w;\n\n    vec4 shadowmapSize = u_ShadowMapSize;\n\n    //if (coord.z > 0.0 && coord.z < 1.0)\n\t{\n\t#if defined(SHADOW_SOFT_SHADOW_HIGH)\n\t    attenuation = sampleShdowMapFiltered9(u_ShadowMap, coord, shadowmapSize);\n\t#elif defined(SHADOW_SOFT_SHADOW_LOW)\n\t    attenuation = sampleShdowMapFiltered4(u_ShadowMap, coord, shadowmapSize);\n\t#else // hard\n\t    attenuation = SAMPLE_TEXTURE2D_SHADOW(u_ShadowMap, coord);\n\t#endif // SHADOW_SOFT_SHADOW_HIGH\n\t    attenuation = mix(1.0, attenuation, ShadowStrength);\n\t}\n\n    if (coord.z > 0.0 && coord.z < 1.0)\n        return attenuation;\n    return 1.0;\n}\n\n    #endif // CALCULATE_SHADOWS\n\n    // 计算 聚光灯 阴影\n    #if defined(CALCULATE_SPOTSHADOWS)\n\n// 聚光灯阴影坐标\nvec4 getSpotShadowCoord(in vec3 positionWS)\n{\n    vec4 coordinate = u_SpotViewProjectMatrix * vec4(positionWS, 1.0);\n\n    return coordinate;\n}\n\n// 采样聚光灯阴影\nfloat sampleSpotShadowmap(vec4 shadowCoord)\n{\n    float attenuation = 1.0;\n\n    vec3 coord = shadowCoord.xyz / shadowCoord.w;\n    coord.xy = coord.xy * 0.5 + 0.5;\n\n    vec4 shadowmapSize = u_SpotShadowMapSize;\n    // todo\n    //if (coord.z > 0.0 && coord.z < 1.0)\n\t//{\n\t#if defined(SHADOW_SPOT_SOFT_SHADOW_HIGH)\n\t    attenuation = sampleShdowMapFiltered9(u_SpotShadowMap, coord, shadowmapSize);\n\t#elif defined(SHADOW_SPOT_SOFT_SHADOW_LOW)\n\t    attenuation = sampleShdowMapFiltered4(u_SpotShadowMap, coord, shadowmapSize);\n\t#else // hard\n\t    attenuation = SAMPLE_TEXTURE2D_SHADOW(u_SpotShadowMap, coord);\n\t#endif\n\t    attenuation = mix(1.0, attenuation, SpotShadowStrength);\n\t//}\n\n    if (coord.z > 0.0 && coord.z < 1.0)\n        return attenuation;\n    return 1.0;\n}\n\n    #endif // CALCULATE_SPOTSHADOWS\n\n#endif // ShadowSampler_lib";

    var SceneFogGLSL = "#if !defined(SceneFog_lib)\n    #define SceneFog_lib\n\n    #ifdef FOG\nvarying float v_fogFactor;\nfloat getFogFactor()\n{\n    return v_fogFactor;\n}\n\nvec3 scenUnlitFog(in vec3 color)\n{\n    float lerpFact = getFogFactor();\n\t#ifdef ADDTIVEFOG\n    lerpFact = clamp(lerpFact, 0.0, 1.0);\n    return mix(vec3(0.0), color, lerpFact);\n\t#else\n    lerpFact = clamp(lerpFact, 0.0, 1.0);\n    return mix(u_FogColor.rgb, color, lerpFact);\n\t#endif // ADDTIVEFOG\n}\n\nvec3 sceneLitFog(in vec3 color)\n{\n    float lerpFact = getFogFactor();\n    lerpFact = clamp(lerpFact, 0.0, 1.0);\n    return mix(u_FogColor.rgb, color, lerpFact);\n}\n\n    #endif\n#endif // SceneFog_lib";

    var SceneFogInputGLSL = "#if !defined(SceneFog_lib)\n    #define SceneFog_lib\n\n    #ifdef FOG\nvarying float v_fogFactor;\nvoid FogHandle(in float fact)\n{\n    float lerpFact = 0.0;\n\t#ifdef FOG_EXP\n    lerpFact = fact * (u_FogParams.z / log(2.0));\n    lerpFact = exp2(-lerpFact);\n\t#elif defined(FOG_EXP2)\n    lerpFact = fact * (u_FogParams.z / sqrt(log(2.0)));\n    lerpFact = exp2(-lerpFact);\n\t#else // default FOG_LINEAR\n    lerpFact = (-1.0 * fact / (u_FogParams.y - u_FogParams.x) + u_FogParams.y / (u_FogParams.y - u_FogParams.x));\n\t#endif\n    v_fogFactor = lerpFact;\n}\n    #endif\n#endif // SceneFog_lib";

    var LightingGLSL = "#if !defined(Lighting_lib)\n    #define Lighting_lib\n\n    #include \"ShadowSampler.glsl\";\n\nstruct Light {\n    vec3 color;\n    vec3 dir;\n    float attenuation;\n};\n\nstruct DirectionLight {\n    vec3 color;\n    vec3 direction;\n    float attenuation;\n    int lightMode;\n};\n\nstruct PointLight {\n    vec3 color;\n    vec3 position;\n    float range;\n    float attenuation;\n    int lightMode;\n};\n\nstruct SpotLight {\n    vec3 color;\n    vec3 position;\n    float range;\n    vec3 direction;\n    float spot;\n    float attenuation;\n    int lightMode;\n};\n\n    #define LightMode_Mix      0\n    #define LightMode_RealTime 1\n\nint getAttenuationByMode(float lightMapMode)\n{\n    #ifdef LIGHTMAP // mix 0 realtime 1\n    return int(lightMapMode);\n    #else // LIGHTMAP\n\n\t#ifdef VOLUMETRICGI\n    return int(lightMapMode);\n\t#endif // VOLUMETRICGI\n\n    #endif // LIGHTMAP\n    return LightMode_RealTime;\n}\n\n    #if defined(DIRECTIONLIGHT) || defined(POINTLIGHT) || defined(SPOTLIGHT)\n\n\t#define LIGHTING\n\n// 灯光衰减函数\nfloat attenuation(in vec3 L, in float invLightRadius)\n{\n    float fRatio = clamp(length(L) * invLightRadius, 0.0, 1.0);\n    fRatio *= fRatio;\n    return 1.0 / (1.0 + 25.0 * fRatio) * clamp(4.0 * (1.0 - fRatio), 0.0, 1.0);\n}\n\n// 平行光\nLight getLight(in DirectionLight directionLight)\n{\n    Light light;\n    light.color = directionLight.color;\n    light.dir = directionLight.direction;\n    light.attenuation = directionLight.attenuation;\n    return light;\n}\n\n// 点光\nLight getLight(in PointLight pointLight, in vec3 normalWS, in vec3 positionWS)\n{\n    vec3 lightDirection = positionWS - pointLight.position;\n    float rangeAttenuate = attenuation(lightDirection, 1.0 / pointLight.range);\n\n    Light light;\n    light.color = pointLight.color * rangeAttenuate;\n    light.dir = normalize(lightDirection);\n    light.attenuation = pointLight.attenuation;\n    return light;\n}\n\n// 聚光灯\nLight getLight(in SpotLight spotLight, in vec3 normalWS, in vec3 positionWS)\n{\n    vec3 lightDirection = positionWS - spotLight.position;\n    vec3 normalizeLightDir = normalize(lightDirection);\n\n    vec2 cosAngles = cos(vec2(spotLight.spot, spotLight.spot * 0.5) * 0.5);\n    float dirAttenuate = dot(spotLight.direction, normalizeLightDir);\n    dirAttenuate *= smoothstep(cosAngles.x, cosAngles.y, dirAttenuate);\n\n    float rangeAttenuate = attenuation(lightDirection, 1.0 / spotLight.range);\n\n    Light light;\n    light.color = spotLight.color * rangeAttenuate * dirAttenuate;\n    light.dir = normalizeLightDir;\n    light.attenuation = spotLight.attenuation;\n    return light;\n}\n\n\t#ifdef LEGACYSINGLELIGHTING\n\t    #define CalculateLightCount 1\n\t    #define DirectionCount\t1\n\n\t    #ifdef DIRECTIONLIGHT\nuniform vec3 u_DirLightColor;\nuniform vec3 u_DirLightDirection;\nuniform int u_DirLightMode;\n\t    #endif // DIRECTIONLIGHT\n\n\t    #ifdef POINTLIGHT\n// uniform PointLight u_PointLight;\nuniform vec3 u_PointLightColor;\nuniform vec3 u_PointLightPos;\nuniform float u_PointLightRange;\nuniform int u_PointLightMode;\n\t    #endif // POINTLIGHT\n\n\t    #ifdef SPOTLIGHT\n// uniform SpotLight u_SpotLight;\nuniform vec3 u_SpotLightPos;\nuniform vec3 u_SpotLightColor;\nuniform vec3 u_SpotLightDirection;\nuniform float u_SpotLightRange;\nuniform float u_SpotLightSpot;\nuniform int u_SpotLightMode;\n\t    #endif // SPOTLIGHT\n\n\t#else // LEGACYSINGLELIGHTING\n\t    #define CalculateLightCount MAX_LIGHT_COUNT\n\t    #define DirectionCount\tu_DirationLightCount\n\nuniform sampler2D u_LightBuffer;\n\n\t    #ifdef DIRECTIONLIGHT\nuniform mediump int u_DirationLightCount;\n\t    #endif\n\n\t    #if defined(POINTLIGHT) || defined(SPOTLIGHT)\nconst int c_ClusterBufferWidth = CLUSTER_X_COUNT * CLUSTER_Y_COUNT;\nint c_ClusterBufferHeight = CLUSTER_Z_COUNT * (1 + int(ceil(float(MAX_LIGHT_COUNT_PER_CLUSTER) / 4.0))); //兼容WGSL\nconst int c_ClusterBufferFloatWidth = c_ClusterBufferWidth * 4;\nuniform sampler2D u_LightClusterBuffer;\n\nint getLightIndex(in int offset, in int index)\n{\n    int totalOffset = offset + index;\n    int row = totalOffset / c_ClusterBufferFloatWidth;\n    int lastRowFloat = totalOffset - row * c_ClusterBufferFloatWidth;\n    int col = lastRowFloat / 4;\n    vec2 uv = vec2((float(col) + 0.5) / float(c_ClusterBufferWidth), (float(row) + 0.5) / float(c_ClusterBufferHeight));\n    vec4 texPixel = texture2D(u_LightClusterBuffer, uv);\n    int pixelComponent = lastRowFloat - col * 4;\n\n\t\t#ifdef GRAPHICS_API_GLES3\n    return int(texPixel[pixelComponent]);\n\t\t#else\n    if (pixelComponent == 0)\n\treturn int(texPixel.x);\n    else if (pixelComponent == 1)\n\treturn int(texPixel.y);\n    else if (pixelComponent == 2)\n\treturn int(texPixel.z);\n    else\n\treturn int(texPixel.w);\n\t\t#endif\n}\n\t    #endif // POINTLIGHT || SPOTLIGHT\n\n\t#endif // LEGACYSINGLELIGHTING\n\n\t#ifdef DIRECTIONLIGHT\nDirectionLight getDirectionLight(in int index, in vec3 positionWS)\n{\n    DirectionLight light;\n\t    #ifdef LEGACYSINGLELIGHTING\n    light.color = u_DirLightColor;\n    light.direction = u_DirLightDirection;\n    light.attenuation = 1.0;\n    light.lightMode = getAttenuationByMode(float(u_DirLightMode));\n\t    #else // LEGACYSINGLELIGHTING\n    float v = (float(index) + 0.5) / float(CalculateLightCount);\n    vec4 p1 = texture2D(u_LightBuffer, vec2(0.125, v));\n    vec4 p2 = texture2D(u_LightBuffer, vec2(0.375, v));\n    light.color = p1.rgb;\n    light.direction = p2.rgb;\n    light.attenuation = 1.0;\n    light.lightMode = getAttenuationByMode(p1.a);\n\t    #endif // LEGACYSINGLELIGHTING\n\n\t    #if defined(CALCULATE_SHADOWS)\n    if (index == 0)\n\t{\n\t    vec4 shadowCoord = getShadowCoord(positionWS);\n\t    float shadowAttenuation = sampleShadowmap(shadowCoord);\n\t    light.attenuation = shadowAttenuation;\n\t}\n\t    #endif // CALCULATE_SHADOWS\n\n    return light;\n}\n\t#endif // DIRECTIONLIGHT\n\n\t#if defined(POINTLIGHT) || defined(SPOTLIGHT)\nivec4 getClusterInfo(mat4 viewMatrix, vec4 viewport, vec3 positionWS, vec4 fragCoord, vec4 projectParams)\n{\n\t    #ifdef LEGACYSINGLELIGHTING\n    return ivec4(1, 1, 0, 0);\n\t    #else // LEGACYSINGLELIGHTING\n    // todo  这个地方 用 positionVS 替换?\n    vec3 viewPos = vec3(viewMatrix * vec4(positionWS, 1.0));\n    int clusterXIndex = int(floor(fragCoord.x / (float(viewport.z) / float(CLUSTER_X_COUNT))));\n    int clusterYIndex = int(floor((viewport.w * (projectParams.z < 0.0 ? 0.0 : 1.0) - fragCoord.y * projectParams.z) / (float(viewport.w) / float(CLUSTER_Y_COUNT))));\n    float zSliceParam = float(CLUSTER_Z_COUNT) / log2(projectParams.y / projectParams.x);\n    int clusterZIndex = int(floor(log2(-viewPos.z) * zSliceParam - log2(projectParams.x) * zSliceParam));\n    // todo 化简\n    vec2 uv = vec2((float(clusterXIndex + clusterYIndex * CLUSTER_X_COUNT) + 0.5) / float(c_ClusterBufferWidth), (float(clusterZIndex) + 0.5) / float(c_ClusterBufferHeight));\n    vec4 clusterPixel = texture2D(u_LightClusterBuffer, uv);\n    return ivec4(clusterPixel); // X:Point Count Y:Spot Count Z、W:Light Offset\n\t    #endif // LEGACYSINGLELIGHTING\n}\n\t#endif // POINTLIGHT || SPOTLIGHT\n\n\t#ifdef POINTLIGHT\nPointLight getPointLight(in int index, in ivec4 clusterInfo, in vec3 positionWS)\n{\n\n    PointLight light;\n\t    #ifdef LEGACYSINGLELIGHTING\n    light.color = u_PointLightColor;\n    light.position = u_PointLightPos;\n    light.range = u_PointLightRange;\n    light.attenuation = 1.0;\n    light.lightMode = getAttenuationByMode(float(u_PointLightMode));\n\t    #else // LEGACYSINGLELIGHTING\n    // todo  重复计算\n    int indexOffset = clusterInfo.z * c_ClusterBufferFloatWidth + clusterInfo.w;\n    int pointIndex = getLightIndex(indexOffset, index);\n    float v = (float(pointIndex) + 0.5) / float(CalculateLightCount);\n    vec4 p1 = texture2D(u_LightBuffer, vec2(0.125, v));\n    vec4 p2 = texture2D(u_LightBuffer, vec2(0.375, v));\n    light.color = p1.rgb;\n    light.range = p1.a;\n    light.position = p2.rgb;\n    light.attenuation = 1.0;\n    light.lightMode = getAttenuationByMode(p2.a);\n\t    #endif // LEGACYSINGLELIGHTING\n    return light;\n}\n\t#endif // POINTLIGHT\n\n\t#ifdef SPOTLIGHT\nSpotLight getSpotLight(in int index, in ivec4 clusterInfo, in vec3 positionWS)\n{\n    SpotLight light;\n\n\t    #ifdef LEGACYSINGLELIGHTING\n    light.color = u_SpotLightColor;\n    light.position = u_SpotLightPos;\n    light.range = u_SpotLightRange;\n    light.direction = u_SpotLightDirection;\n    light.spot = u_SpotLightSpot;\n    light.attenuation = 1.0;\n    light.lightMode = getAttenuationByMode(float(u_SpotLightMode));\n\t    #else // LEGACYSINGLELIGHTING\n    // todo  重复计算\n    int indexOffset = clusterInfo.z * c_ClusterBufferFloatWidth + clusterInfo.w;\n    int spotIndex = getLightIndex(indexOffset, index + clusterInfo.x);\n    float v = (float(spotIndex) + 0.5) / float(CalculateLightCount);\n    vec4 p1 = texture2D(u_LightBuffer, vec2(0.125, v));\n    vec4 p2 = texture2D(u_LightBuffer, vec2(0.375, v));\n    vec4 p3 = texture2D(u_LightBuffer, vec2(0.625, v));\n    light.color = p1.rgb;\n    light.range = p1.a;\n    light.position = p2.rgb;\n    light.spot = p2.a;\n    light.direction = p3.rgb;\n    light.attenuation = 1.0;\n    light.lightMode = getAttenuationByMode(p3.a);\n\t    #endif // LEGACYSINGLELIGHTING\n\n\t    #if defined(CALCULATE_SPOTSHADOWS)\n    if (index == 0)\n\t{\n\t    vec4 shadowCoord = getSpotShadowCoord(positionWS);\n\t    float shadowAttenuation = sampleSpotShadowmap(shadowCoord);\n\t    light.attenuation = shadowAttenuation;\n\t}\n\t    #endif // CALCULATE_SPOTSHADOWS\n\n    return light;\n}\n\t#endif // SPOTLIGHT\n\n    #endif // DIRECTIONLIGHT || POINTLIGHT || SPOTLIGHT\n\n#endif // Lighting_lib";

    var GlobalIlluminationGLSL = "#if !defined(globalIllumination_lib)\n    #define globalIllumination_lib\n\n    #ifdef VOLUMETRICGI\n\t#include \"VolumetricGI.glsl\";\n    #endif // VOLUMETRICGI\n\nvec3 rotateByYAixs(in vec3 normal)\n{\n    float co = cos(u_GIRotate);\n    float si = sin(u_GIRotate);\n    float x = normal.x * co - normal.z * si;\n    float z = normal.x * si + normal.z * co;\n    return vec3(x, normal.y, z);\n}\n\nvec4 rotateByYAixs(in vec4 normal)\n{\n    float co = cos(u_GIRotate);\n    float si = sin(u_GIRotate);\n    float x = normal.x * co - normal.z * si;\n    float z = normal.x * si + normal.z * co;\n    return vec4(x, normal.y, z, normal.w);\n}\nuniform float u_AmbientIntensity;\nuniform float u_ReflectionIntensity;\n\n    #ifdef GI_IBL\n\nuniform vec3 u_IblSH[9];\n\nuniform samplerCube u_IBLTex;\nuniform float u_IBLRoughnessLevel;\n\n//#define IBL_ROUGHNESS_LEVEL u_IBLRoughnessLevel //兼容WGSL\n\n// todo 格式\nvec3 diffuseIrradiance(in vec3 normalWS)\n{\n    // todo cmeng 生成的数据问题， 临时转换下\n    vec3 n = normalWS * vec3(-1.0, 1.0, 1.0);\n    n = rotateByYAixs(n);\n    return max(\n\t       u_IblSH[0]\n\t\t   + u_IblSH[1] * n.y\n\t\t   + u_IblSH[2] * n.z\n\t\t   + u_IblSH[3] * n.x\n\t\t   + u_IblSH[4] * (n.y * n.x)\n\t\t   + u_IblSH[5] * (n.y * n.z)\n\t\t   + u_IblSH[6] * (3.0 * n.z * n.z - 1.0)\n\t\t   + u_IblSH[7] * (n.z * n.x)\n\t\t   + u_IblSH[8] * (n.x * n.x - n.y * n.y),\n\t       0.0)\n\t* u_AmbientIntensity;\n}\n\nvec3 diffuseIrradiance(in vec3 normalWS, in vec3 positionWS, in vec3 viewDir)\n{\n\t#ifdef VOLUMETRICGI\n    vec3 surfaceBias = VolumetricGISurfaceBias(normalWS, viewDir);\n    return VolumetricGIVolumeIrradiance(positionWS, surfaceBias, normalWS) * u_AmbientIntensity;\n\t#else // VOLUMETRICGI\n    return diffuseIrradiance(normalWS);\n\t#endif // VOLUMETRICGI\n}\n\nvec3 specularRadiance(in vec3 r, in float perceptualRoughness)\n{\n    float lod = u_IBLRoughnessLevel * perceptualRoughness * (2.0 - perceptualRoughness); //兼容WGSL\n\n    // todo 临时转换\n    vec3 reflectDir = r * vec3(-1.0, 1.0, 1.0);\n\n    // todo rotateY SceneConfig\n    reflectDir = rotateByYAixs(reflectDir);\n\n    // todo float 编码 ?\n    #ifdef LOD_TEXTURE_SAMPLE\n    vec4 reflectSampler = textureCubeLodEXT(u_IBLTex, reflectDir, lod);\n    #else\n    vec4 reflectSampler = textureLod(u_IBLTex, reflectDir, lod); //兼容WGSL\n    #endif\n\n\t#ifdef IBL_RGBD\n    return decodeRGBD(reflectSampler) * u_ReflectionIntensity;\n\t#else // IBL_RGBD\n    return reflectSampler.rgb * u_ReflectionIntensity;\n\t#endif // IBL_RGBD\n}\n\n    #endif // GI_IBL\n\n    #ifdef GI_LEGACYIBL\n\nuniform vec4 u_AmbientSHAr;\nuniform vec4 u_AmbientSHAg;\nuniform vec4 u_AmbientSHAb;\nuniform vec4 u_AmbientSHBr;\nuniform vec4 u_AmbientSHBg;\nuniform vec4 u_AmbientSHBb;\nuniform vec4 u_AmbientSHC;\n\n\t#define LAYA_SPECCUBE_LOD_STEPS 6.0\nuniform samplerCube u_ReflectTexture;\nuniform vec4 u_ReflectCubeHDRParams;\n\nvec3 shEvalLinearL0L1(in vec4 normal)\n{\n    vec3 x;\n    x.r = dot(u_AmbientSHAr, normal);\n    x.g = dot(u_AmbientSHAg, normal);\n    x.b = dot(u_AmbientSHAb, normal);\n    return x;\n}\n\nvec3 shEvalLinearL2(in vec4 normal)\n{\n    vec3 x1, x2;\n    // 4 of the quadratic (L2) polynomials\n    vec4 vB = normal.xyzz * normal.yzzx;\n    x1.r = dot(u_AmbientSHBr, vB);\n    x1.g = dot(u_AmbientSHBg, vB);\n    x1.b = dot(u_AmbientSHBb, vB);\n\n    // Final (5th) quadratic (L2) polynomial\n    float vC = normal.x * normal.x - normal.y * normal.y;\n    x2 = u_AmbientSHC.rgb * vC;\n\n    return x1 + x2;\n}\n\nvec3 diffuseIrradiance(in vec3 normalWS)\n{\n    // todo -x 坐标转换\n    vec4 normal = vec4(-normalWS.x, normalWS.yz, 1.0);\n\n    // TODO rotate y SceneConfig\n\n    normal = rotateByYAixs(normal);\n\n    vec3 ambientContrib = shEvalLinearL0L1(normal);\n    ambientContrib += shEvalLinearL2(normal);\n    vec3 ambient = max(vec3(0.0), ambientContrib);\n\n    return ambient * u_AmbientIntensity;\n}\n\nvec3 diffuseIrradiance(in vec3 normalWS, in vec3 positionWS, in vec3 viewDir)\n{\n\t#ifdef VOLUMETRICGI\n    vec3 surfaceBias = VolumetricGISurfaceBias(normalWS, viewDir);\n    return VolumetricGIVolumeIrradiance(positionWS, surfaceBias, normalWS) * u_AmbientIntensity;\n\t#else // VOLUMETRICGI\n    return diffuseIrradiance(normalWS);\n\t#endif // VOLUMETRICGI\n}\n\nvec3 specularRadiance(in vec3 r, in float perceptualRoughness)\n{\n    float roughness = perceptualRoughness * (1.7 - 0.7 * perceptualRoughness);\n    // todo 临时转换\n    r *= vec3(-1.0, 1.0, 1.0);\n    r = rotateByYAixs(r);\n\n    float lod = roughness * LAYA_SPECCUBE_LOD_STEPS;\n    vec4 rgbm = textureCubeLodEXT(u_ReflectTexture, r, lod);\n    float range = u_ReflectCubeHDRParams.x;\n    vec3 color = decodeRGBM(rgbm, range);\n    color = gammaToLinear(color);\n    return color * u_ReflectionIntensity;\n}\n\n    #endif // GI_LEGACYIBL\n\n    #ifndef GI_IBL\n\t#ifndef GI_LEGACYIBL\n\nuniform vec4 u_AmbientColor;\n\nvec3 diffuseIrradiance(in vec3 normalWS)\n{\n    return u_AmbientColor.rgb * u_AmbientIntensity;\n}\n\nvec3 diffuseIrradiance(in vec3 normalWS, in vec3 positionWS, in vec3 viewDir)\n{\n    return diffuseIrradiance(normalWS);\n}\n\nvec3 specularRadiance(in vec3 r, in float perceptualRoughness)\n{\n    // todo\n    return u_AmbientColor.rgb * u_ReflectionIntensity;\n}\n\n\t#endif // GI_LEGACYIBL\n    #endif // GI_IBL\n\n    #ifdef LIGHTMAP\n\n\t#ifdef UV1\n\t    #define USELIGHTMAP\n\t#endif // UV1\n\nuniform sampler2D u_LightMap;\n\n\t#ifdef LIGHTMAP_DIRECTIONAL\n\nuniform sampler2D u_LightMapDirection;\n\nvec3 DecodeDirectionalLightmap(in vec2 lightmapUV, in vec3 bakeColor, in vec3 normalWS)\n{\n    vec4 dirLightmap = texture2D(u_LightMapDirection, lightmapUV);\n    vec3 lightdir = normalize(dirLightmap.xyz - vec3(0.5)); // 0-1  => -0.5-0.5\n    //根据法线计算半兰伯特\n    float halfLambert = clamp(dot(normalWS, lightdir), 0.0, 1.0) * 0.5 + 0.5;\n    return bakeColor * halfLambert / max(dirLightmap.w, 0.001);\n}\n\n\t#endif // LIGHTMAP_DIRECTIONAL\n\nvec3 getBakedLightmapColor(in vec2 lightmapUV, in vec3 normalWS)\n{\n    vec4 lightmapSampler = texture2D(u_LightMap, lightmapUV);\n\t// todo lightmap rgbm encode color space\n    lightmapSampler.rgb =  decodeRGBM(lightmapSampler,5.0);\n\n\t//#ifdef Gamma_u_LightMap\n    lightmapSampler = gammaToLinear(lightmapSampler);\n\t//#endif // Gamma_u_LightMap\n\n\t#ifdef LIGHTMAP_DIRECTIONAL\n    lightmapSampler.rgb = DecodeDirectionalLightmap(lightmapUV, lightmapSampler.rgb, normalWS);\n\t#endif // LIGHTMAP_DIRECTIONAL\n\n    return lightmapSampler.rgb;\n}\n\n    #endif // LIGHTMAP\n\n    #ifdef SPECCUBE_BOX_PROJECTION\n\nuniform vec3 u_SpecCubeProbePosition;\nuniform vec3 u_SpecCubeBoxMax;\nuniform vec3 u_SpecCubeBoxMin;\n\nvec3 getBoxProjectionReflectedVector(vec3 r, vec3 positionWS)\n{\n    vec3 boxCenter = u_SpecCubeProbePosition;\n    vec3 boxMin = u_SpecCubeBoxMin;\n    vec3 boxMax = u_SpecCubeBoxMax;\n\n    vec3 nr = normalize(r);\n    vec3 rbmax = boxMax - positionWS;\n    vec3 rbmin = boxMin - positionWS;\n    vec3 select = step(vec3(0.0), r);\n    vec3 rbminmax = mix(rbmin, rbmax, select) / nr;\n    float scalar = vecmin(rbminmax);\n    vec3 boxr = nr * scalar + positionWS - boxCenter;\n    return boxr;\n}\n\n    #endif // SPECCUBE_BOX_PROJECTION\n\n#endif // globalIllumination_lib";

    var OctGLSL = "#if !defined(Oct_lib)\n    #define Oct_lib\n\nfloat signNotZero(in float k) { return k >= 0.0 ? 1.0 : -1.0; }\n\nvec2 signNotZero(in vec2 v) { return vec2(signNotZero(v.x), signNotZero(v.y)); }\n\n/**\n * v: normalized sample dir\n * @return: oct encode uv [-1, 1]\n */\nvec2 octEncode(in vec3 v)\n{\n    float l1norm = abs(v.x) + abs(v.y) + abs(v.z);\n    vec2 result = v.xy * (1.0 / l1norm);\n    if (v.z < 0.0)\n\t{\n\t    result = (1.0 - abs(result.yx)) * signNotZero(result.xy);\n\t}\n\n    return result;\n}\n\n/**\n * x: u [-1, 1]\n * y: v [-1, 1]\n * @return: normalized sample dir\n */\nvec3 finalDecode(float x, float y)\n{\n    vec3 v = vec3(x, y, 1.0 - abs(x) - abs(y));\n    if (v.z < 0.0)\n\t{\n\t    v.xy = (1.0 - abs(v.yx)) * signNotZero(v.xy);\n\t}\n    return normalize(v);\n}\n\n/**\n * dir: cubemap sample dir\n * outsize: probe size with border (x: probe x, y: probe y, z: 1 / probe x, w: 1\n * / probe y) gridsize: probe grid size (x: probe x index, y: probe y index, z:\n * grid x size, w: grid y size)\n * @return texture coord [0, 1]\n */\nvec2 textureCoordFromDirection(in vec3 dir, vec4 outSize, vec4 gridSize)\n{\n    vec2 uv = (octEncode(normalize(dir))) * 0.5 + 0.5;\n    uv = uv * (outSize.xy - vec2(2.0, 2.0)) * outSize.zw + outSize.zw;\n    uv = gridSize.xy * (1.0 / gridSize.zw) + uv * (1.0 / gridSize.zw);\n    return uv;\n}\n\n#endif // Oct_lib";

    var GridHelpersGLSL = "#if !defined(GridHelpers_lib)\n    #define GridHelpers_lib\n\nint imod(int x, int y)\n{\n    #ifdef GRAPHICS_API_GLES3\n    return x % y;\n    #else // GRAPHICS_API_GLES3\n    return x - (x / y) * y;\n    #endif // GRAPHICS_API_GLES3\n}\n\nint gridCoordToProbeIndex(in ivec3 probeCoords, const in ivec3 probeCounts)\n{\n    return probeCoords.x + probeCoords.y * probeCounts.x + probeCoords.z * probeCounts.x * probeCounts.y;\n}\n\nivec3 probeIndexToGridcoord(in int probeIndex, const in ivec3 probeCounts)\n{\n    ivec3 iPos;\n    iPos.x = imod(probeIndex, probeCounts.x);\n    iPos.y = imod(probeIndex, (probeCounts.x * probeCounts.y)) / probeCounts.x;\n    iPos.z = probeIndex / (probeCounts.x * probeCounts.y);\n    return iPos;\n\n    //   ivec3 iPos;\n    //   iPos.x = probeIndex & (probeCounts.x - 1);\n    //   iPos.y = (probeIndex & ((probeCounts.x * probeCounts.y) - 1)) >>\n    //            findMSB(probeCounts.x);\n    //   iPos.z = probeIndex >> findMSB(probeCounts.x * probeCounts.y);\n    //   return iPos;\n}\n\nvec3 gridCoordToPosition(in ivec3 coord, const in vec3 probeStep,\n    const in vec3 probeStartPosition)\n{\n    return (vec3(coord) + 0.5) * probeStep + probeStartPosition;\n}\n\nivec3 baseGridCoord(in vec3 position, in vec3 probeStep,\n    in vec3 probeStartPosition, in ivec3 probeCounts)\n{\n    probeStartPosition += 0.5 * probeStep;\n    return ivec3(clamp(vec3((position - probeStartPosition) / probeStep),\n\tvec3(0, 0, 0), vec3(probeCounts) - vec3(1, 1, 1)));\n}\n\n#endif // GridHelpers_lib";

    var VolumetricGIGLSL = "// https://jcgt.org/published/0008/02/01/\n\n#if !defined(VolumetricGI_lib)\n    #define VolumetricGI_lib\n\n    #include \"Oct.glsl\";\n    #include \"GridHelpers.glsl\";\n\nuniform vec3 u_VolGIProbeCounts;\nuniform vec3 u_VolGIProbeStep;\nuniform vec3 u_VolGIProbeStartPosition;\nuniform vec4 u_VolGIProbeParams;\n\nstruct VolumetricGI {\n    vec3 probeCounts;\n    vec3 probeStep;\n    vec3 probeStartPosition;\n    vec4 probeParams; // x: irradianceTexels, y: distanceTexels, z: normalBias, w: viewBias\n};\n\nuniform sampler2D u_ProbeIrradiance;\nuniform sampler2D u_ProbeDistance;\n\nvec2 porbeGridCoordToTextureGridCoord(in ivec3 porbeGridCoord,\n    in ivec3 probeCounts,\n    in vec2 textureGridSize)\n{\n    int probeIndex = gridCoordToProbeIndex(porbeGridCoord, probeCounts);\n    ivec2 index;\n    index.x = imod(probeIndex, (probeCounts.x * probeCounts.y));\n    index.y = probeIndex / (probeCounts.x * probeCounts.y);\n\n    vec2 textureGridCoord = vec2(index);\n    textureGridCoord.y = textureGridCoord.y;\n    return textureGridCoord;\n}\n\nvec3 VolumetricGISurfaceBias(in vec3 surfaceNormal, in vec3 cameraDirection)\n{\n    return surfaceNormal * u_VolGIProbeParams.z + cameraDirection * u_VolGIProbeParams.w;\n}\n\nvec3 VolumetricGIVolumeIrradiance(in vec3 worldPosition, in vec3 surfaceBias,\n    in vec3 direction)\n{\n    // direction *= vec3(-1.0, 1.0, 1.0);\n    ivec3 porbeCounts = ivec3(u_VolGIProbeCounts);\n    vec3 probeStep = u_VolGIProbeStep;\n    vec3 probeStartPosition = u_VolGIProbeStartPosition;\n    vec2 volumeCounts = vec2(porbeCounts.x * porbeCounts.y, porbeCounts.z);\n    vec4 irradianceTexels = vec4(u_VolGIProbeParams.x, u_VolGIProbeParams.x, 1.0 / u_VolGIProbeParams.x, 1.0 / u_VolGIProbeParams.x);\n    vec4 distanceTexels = vec4(u_VolGIProbeParams.y, u_VolGIProbeParams.y, 1.0 / u_VolGIProbeParams.y, 1.0 / u_VolGIProbeParams.y);\n\n    ivec3 maxGridCoord = porbeCounts - ivec3(1);\n\n    vec3 irradiance = vec3(0.0);\n    float accumulatedWeights = 0.0;\n\n    // Bias the world space position\n    vec3 biasedWorldPosition = worldPosition + surfaceBias;\n\n    // Get the 3D grid coordinates of the probe nearest the biased world position\n    // (i.e. the \"base\" probe)\n    ivec3 baseProbeCoords = baseGridCoord(biasedWorldPosition, probeStep,\n\tprobeStartPosition, porbeCounts);\n\n    // Get the world-space position of the base probe (ignore relocation)\n    vec3 baseProbeWorldPosition = gridCoordToPosition(baseProbeCoords, probeStep, probeStartPosition);\n\n    // Clamp the distance (in grid space) between the given point and the base\n    // probe's world position (on each axis) to [0, 1]\n    vec3 gridSpaceDistance = biasedWorldPosition - baseProbeWorldPosition;\n\n    vec3 alpha = clamp(gridSpaceDistance / probeStep, vec3(0.0), vec3(1.0));\n\n    // Iterate over the 8 closest probes and accumulate their contributions\n    for (int probeIndex = 0; probeIndex < 8; probeIndex++)\n\t{\n\t    // Compute the offset to the adjacent probe in grid coordinates by sourcing\n\t    // the offsets from the bits of the loop index: x = bit 0, y = bit 1, z =\n\t    // bit 2\n\t    // ivec3 adjacentProbeOffset = ivec3(probeIndex, probeIndex >> 1, probeIndex >> 2) & ivec3(1, 1, 1);\n\t\tivec3 adjacentProbeOffset = ivec3(imod(probeIndex, 2), imod((probeIndex / 2), 2),imod( (probeIndex / 4), 2));\n\n\t    // Get the 3D grid coordinates of the adjacent probe by adding the offset to\n\t    // the base probe and clamping to the grid boundaries\n\t    ivec3 adjacentProbeCoords = ivec3(clamp(vec3(baseProbeCoords + adjacentProbeOffset), vec3(0), vec3(maxGridCoord)));\n\n\t    // Get the adjacent probe's world position\n\t    vec3 adjacentProbeWorldPosition = gridCoordToPosition(adjacentProbeCoords, probeStep, probeStartPosition);\n\n\t    // Compute the distance and direction from the (biased and non-biased)\n\t    // shading point and the adjacent probe\n\t    vec3 worldPosToAdjProbe = normalize(adjacentProbeWorldPosition - worldPosition);\n\t    vec3 biasedPosToAdjProbe = normalize(adjacentProbeWorldPosition - biasedWorldPosition);\n\t    float biasedPosToAdjProbeDist = distance(adjacentProbeWorldPosition, biasedWorldPosition);\n\n\t    // Compute trilinear weights based on the distance to each adjacent probe to\n\t    // smoothly transition between probes. adjacentProbeOffset is binary, so\n\t    // we're using a 1-alpha when adjacentProbeOffset = 0 and alpha when\n\t    // adjacentProbeOffset = 1.\n\t    vec3 trilinear = max(vec3(0.001), mix(1.0 - alpha, alpha, vec3(adjacentProbeOffset)));\n\t    float trilinearWeight = trilinear.x * trilinear.y * trilinear.z;\n\t    float weight = 1.0;\n\n\t    // A naive soft backface weight would ignore a probe when\n\t    // it is behind the surface. That's good for walls, but for\n\t    // small details inside of a room, the normals on the details\n\t    // might rule out all of the probes that have mutual visibility\n\t    // to the point. We instead use a \"wrap shading\" test. The small\n\t    // offset at the end reduces the \"going to zero\" impact.\n\t    float warpShading = (dot(worldPosToAdjProbe, direction) + 1.0) * 0.5;\n\t    weight *= (warpShading * warpShading) * 0.2;\n\n\t    vec2 textureGridCoord = porbeGridCoordToTextureGridCoord(\n\t\tadjacentProbeCoords, porbeCounts, volumeCounts);\n\t    // compute the octahedral coordinates of the adjacent probe\n\t    vec2 probeTextureUV = textureCoordFromDirection(-biasedPosToAdjProbe, distanceTexels,\n\t\tvec4(textureGridCoord, volumeCounts));\n\t    // Sample the probe's distance texture to get the mean distance to nearby\n\t    // surfaces\n\t    vec3 filteredDistance = texture2D(u_ProbeDistance, probeTextureUV).xyz;\n\t    // Find the variance of the mean distance\n\t    float variance = abs(filteredDistance.x * filteredDistance.x - filteredDistance.y);\n\n\t    // Occlusion test\n\t    float chebyshevWeight = 1.0;\n\t    if (biasedPosToAdjProbeDist > filteredDistance.x)\n\t\t{\n\t\t    float v = biasedPosToAdjProbeDist - filteredDistance.x;\n\t\t    // v must be greater than 0, which is guaranteed by the if condition\n\t\t    // above.\n\t\t    chebyshevWeight = variance / (variance + (v * v));\n\n\t\t    // Increase the contrast in the weight\n\t\t    chebyshevWeight = max(chebyshevWeight * chebyshevWeight * chebyshevWeight, 0.0);\n\t\t}\n\n\t    if (filteredDistance.z < 1.0)\n\t\t{\n\t\t    chebyshevWeight = 1.0;\n\t\t}\n\n\t    // Avoid visibility weights ever going all the way to zero because\n\t    // when *no* probe has visibility we need a fallback value\n\t    weight *= max(0.05, chebyshevWeight);\n\n\t    // Avoid a weight of zero\n\t    weight = max(0.000001, weight);\n\n\t    // A small amount of light is visible due to logarithmic perception, so\n\t    // crush tiny weights but keep the curve continuous\n\t    const float crushThreshold = 0.2;\n\t    if (weight < crushThreshold)\n\t\t{\n\t\t    weight *= (weight * weight) * (1.0 / (crushThreshold * crushThreshold));\n\t\t}\n\n\t    // Apply the trilinear weights\n\t    weight *= trilinearWeight;\n\n\t    probeTextureUV = textureCoordFromDirection(\n\t\tdirection, irradianceTexels, vec4(textureGridCoord, volumeCounts));\n\n\t    // Sample the probe's irradiance\n\t    vec3 probeIrradiance = linearToGamma(texture2D(u_ProbeIrradiance, probeTextureUV).rgb);\n\n\t    irradiance += (probeIrradiance * weight);\n\t    accumulatedWeights += weight;\n\t}\n\n    if (accumulatedWeights == 0.0)\n\t{\n\t    return vec3(0.0);\n\t}\n\n    irradiance *= (1.0 / accumulatedWeights); // Normalize by the accumulated weights\n\n    irradiance = gammaToLinear(irradiance);\n\n    return irradiance;\n}\n\n#endif // VolumetricGI_lib";

    var BlinnPhongLightingGLSL = "#if !defined(BlinnPhongLighting_lib)\n    #define BlinnPhongLighting_lib\n\n    #include \"Lighting.glsl\";\n    #include \"globalIllumination.glsl\";\n\nstruct PixelInfo {\n    vec3 positionWS;\n\n    vec3 vertexNormalWS;\n    vec3 normalWS;\n\n    vec3 viewDir;\n\n    #ifdef LIGHTMAP\n\t#ifdef UV1\n    vec2 lightmapUV;\n\t#endif // UV1\n    #endif // LIGHTMAP\n};\n\nstruct Surface {\n    vec3 diffuseColor;\n    vec3 specularColor;\n    float shininess;\n    vec3 gloss;\n\n    vec3 normalTS;\n\n    float alpha;\n    float alphaClip;\n};\n\nvec3 BlinnPhongLighting(in Surface surface, in Light light, in PixelInfo pixel)\n{\n    vec3 l = normalize(-light.dir);\n    vec3 v = pixel.viewDir;\n\n    vec3 normalWS = pixel.normalWS;\n\n    vec3 diffuseColor = surface.diffuseColor;\n    float shininess = surface.shininess;\n    vec3 specularColor = surface.specularColor;\n    vec3 gloss = surface.gloss;\n\n    // difffuse\n    float ndl = max(0.0, dot(normalWS, l));\n    vec3 lightDiffuse = light.color * diffuseColor * ndl;\n\n    // specular\n    mediump vec3 h = normalize(v + l);\n    lowp float ndh = max(0.0, dot(h, normalWS));\n    float specularIntensity = pow(ndh, shininess * 128.0);\n    vec3 lightSpecular = light.color * specularColor * specularIntensity * gloss;\n\n    return lightDiffuse + lightSpecular;\n}\n\nvec3 BlinnPhongGI(const in Surface surface, const in PixelInfo info)\n{\n    vec3 indirect = vec3(0.0);\n\n    #ifdef LIGHTMAP\n\t#ifdef UV1\n\n    vec2 lightmapUV = info.lightmapUV;\n    vec3 bakedColor = getBakedLightmapColor(lightmapUV, info.normalWS);\n\n    // todo  surface.diffuseColor ？\n    indirect = bakedColor * surface.diffuseColor;\n\n\t#endif // UV1\n\n    #else // LIGHTMAP\n\n    vec3 n = info.normalWS;\n    indirect = diffuseIrradiance(n) * surface.diffuseColor;\n\n    #endif // LIGHTMAP\n\n    return indirect;\n}\n\n#endif // BlinnPhongLighting_lib";

    var PBRLightingGLSL = "#if !defined(PBRLighting_lib)\n    #define PBRLighting_lib\n\n    #include \"Lighting.glsl\";\n\n    // 精度\n    #if !defined(GL_FRAGMENT_PRECISION_HIGH)\n\t#define MIN_PERCEPTUAL_ROUGHNESS 0.089\n\t#define MIN_ROUGHNESS\t\t 0.007921\n    #else\n\t#define MIN_PERCEPTUAL_ROUGHNESS 0.045\n\t#define MIN_ROUGHNESS\t\t 0.002025\n    #endif\n\n    #define MIN_N_DOT_V 1e-4\n\n    #include \"BRDF.glsl\";\n\nstruct PixelInfo {\n    vec3 positionWS;\n\n    vec3 vertexNormalWS;\n    vec3 normalWS;\n    vec3 tangentWS;\n    vec3 biNormalWS;\n\n    vec3 viewDir;\n    float NoV;\n\n    vec3 dfg;\n    vec3 energyCompensation;\n\n    #ifdef IRIDESCENCE\n    vec3 iridescenceFresnel;\n    #endif // IRIDESCENCE\n\n    #ifdef CLEARCOAT\n    vec3 clearCoatNormal;\n    float clearCoatNoV;\n    #endif // CLEARCOAT\n\n    #ifdef SHEEN\n    float sheenScaling;\n    float sheenDfg;\n    #endif // SHEEN\n\n    #ifdef ANISOTROPIC\n    vec3 anisotropicT;\n    vec3 anisotropicB;\n    float ToV;\n    float BoV;\n    float at;\n    float ab;\n    #endif // ANISOTROPIC\n\n    #ifdef THICKNESS\n    vec4 worldScale;\n    #endif // THICKNESS\n\n    #ifdef LIGHTMAP\n\t#ifdef UV1\n    vec2 lightmapUV;\n\t#endif // UV1\n    #endif // LIGHTMAP\n};\n\nstruct Surface {\n    vec3 diffuseColor;\n    float alpha;\n    vec3 f0;\n    vec3 f90;\n    float roughness;\n    float perceptualRoughness;\n    float occlusion;\n\n    #ifdef EMISSION\n    vec3 emissionColor;\n    #endif // EMISSION\n\n    vec3 normalTS;\n\n    float ior;\n\n    #ifdef CLEARCOAT\n    float clearCoat;\n    float clearCoatRoughness;\n    float clearCoatPerceptualRoughness;\n\t#ifdef CLEARCOAT_NORMAL\n    vec3 clearCoatNormalTS;\n\t#endif // CLEARCOAT_NORMAL\n    #endif // CLEARCOAT\n\n    #ifdef ANISOTROPIC\n    float anisotropy;\n    vec2 anisotropyDirection;\n    #endif // ANISOTROPIC\n\n    #ifdef IRIDESCENCE\n    float iridescence;\n    float iridescenceIor;\n    float iridescenceThickness;\n    #endif // IRIDESCENCE\n\n    #ifdef SHEEN\n    vec3 sheenColor;\n    float sheenRoughness;\n    float sheenPerceptualRoughness;\n    #endif // SHEEN\n\n    #ifdef TRANSMISSION\n    float transmission;\n    #endif // TRANSMISSION\n\n    #ifdef THICKNESS\n    float thickness;\n    vec3 attenuationColor;\n    float attenuationDistance;\n    #endif // THICKNESS\n};\n\nstruct LightParams {\n    vec3 l;\n    vec3 h;\n    float NoL;\n    float NoH;\n    float LoH;\n    float VoH;\n\n    #ifdef CLEARCOAT\n    float clearCoatNoH;\n    float clearCoatNoL;\n    #endif // CLEARCOAT\n\n    #ifdef ANISOTROPIC\n    float ToL;\n    float BoL;\n    #endif // ANISOTROPIC\n};\n\nvoid initLightParams(inout LightParams params, const in PixelInfo pixel, const in Light light)\n{\n    vec3 v = pixel.viewDir;\n    vec3 n = pixel.normalWS;\n\n    vec3 l = normalize(-light.dir);\n    params.l = l;\n\n    vec3 h = SafeNormalize(v + l);\n    params.h = h;\n    params.NoL = saturate(dot(n, l));\n    params.NoH = saturate(dot(n, h));\n    params.LoH = saturate(dot(l, h));\n    params.VoH = saturate(dot(v, h));\n\n    #ifdef CLEARCOAT\n    params.clearCoatNoL = saturate(dot(pixel.clearCoatNormal, l));\n    params.clearCoatNoH = saturate(dot(pixel.clearCoatNormal, h));\n    #endif // CLEARCOAT\n\n    #ifdef ANISOTROPIC\n    vec3 t = pixel.anisotropicT;\n    vec3 b = pixel.anisotropicB;\n    params.ToL = dot(t, l);\n    params.BoL = dot(b, l);\n    #endif // ANISOTROPIC\n}\n\nvec3 prefilteredDFG_LUT(float roughness, float NoV)\n{\n    vec2 samplePoint = clamp(vec2(NoV, roughness), vec2(0.0, 0.0), vec2(1.0, 1.0));\n    samplePoint.y = 1.0 - samplePoint.y;\n    #if defined(FLOATTEXTURE) && defined(FLOATTEXTURE_FIL_LINEAR)\n    return (texture2D(u_IBLDFG, samplePoint)).rgb;\n    #else\n    return decodeRGBD(texture2D(u_IBLDFG, samplePoint));\n    #endif\n}\n\n// todo remove\nvec2 EnvBRDFApproxLazarov(float roughness, float NoV)\n{\n    vec4 c0 = vec4(-1, -0.0275, -0.572, 0.022);\n    vec4 c1 = vec4(1, 0.0425, 1.04, -0.04);\n    vec4 r = roughness * c0 + c1;\n    float a004 = min(r.x * r.x, exp2(-9.28 * NoV)) * r.x + r.y;\n    vec2 AB = vec2(-1.04, 1.04) * a004 + r.zw;\n    return AB;\n}\n\nfloat dielectricSpecularToF0(float specular)\n{\n    return 0.08 * specular;\n}\n\nfloat dielectricF0ToIor(float f0)\n{\n    return 2.0 / (1.0 - sqrt(min(f0, 0.99))) - 1.0;\n}\n\nfloat dielectricIorToF0(float ior)\n{\n    return pow2((ior - 1.0) / (ior + 1.0));\n}\n\n// input dielectric f0, output surface f0\nvec3 computeF0(vec3 f0, vec3 baseColor, float metallic)\n{\n    return mix(f0, baseColor, metallic);\n}\n\n// input surface f0, output surface f90\nvec3 computeF90(vec3 f0)\n{\n    return vec3(saturate(dot(f0, vec3(50.0 * 0.33))));\n}\n\nvec3 computeDiffuse(vec3 baseColor, float metallic)\n{\n    return (1.0 - metallic) * baseColor;\n}\n\nfloat specularAA(float roughness, in vec3 normalWS)\n{\n\n    #if !defined(GRAPHICS_API_GLES3) && !defined(GL_OES_standard_derivatives)\n\n    return roughness;\n\n    #else // !GRAPHICS_API_GLES3 && !GL_OES_standard_derivatives\n\n    vec3 du = dFdx(normalWS);\n    vec3 dv = dFdy(normalWS);\n\n    float specularAAVariance = 0.15;\n    float specularAAThreshold = 0.04;\n\n    float variance = specularAAVariance * (dot(du, du) + dot(dv, dv));\n    float kernelRoughness = min(2.0 * variance, specularAAThreshold);\n\n    float squareRoughness = saturate(roughness * roughness + kernelRoughness);\n\n    return sqrt(squareRoughness);\n\n    #endif // !GRAPHICS_API_GLES3 && !GL_OES_standard_derivatives\n}\n\nvec3 diffuseLobe(in Surface surface, const in PixelInfo pixel, const in LightParams lightParams)\n{\n    return surface.diffuseColor * Fd_Lambert();\n    // return surface.diffuseColor * Fd_Burley(surface.roughness, pixel.NoV, lightParams.NoL, lightParams.LoH);\n}\n\nvec3 specularLobe(const in Surface surface, const in PixelInfo pixel, const in LightParams lightParams)\n{\n    float roughness = surface.roughness;\n\n    float D = distribution(roughness, lightParams.NoH, lightParams.h, pixel.normalWS);\n    float V = visibility(roughness, pixel.NoV, lightParams.NoL);\n    vec3 F = fresnel(surface.f0, surface.f90, lightParams.LoH);\n\n    return (D * V) * F;\n}\n\n    #ifdef IRIDESCENCE\nvec3 iridescenceDiffuseLobe(in Surface surface, const in PixelInfo pixel, const in LightParams lightParams)\n{\n    vec3 f0 = surface.f0;\n    vec3 f90 = vec3(1.0);\n    vec3 iridescenceFresnel = pixel.iridescenceFresnel;\n    float iridescence = surface.iridescence;\n    float VoH = lightParams.VoH;\n    return surface.diffuseColor * Fd_IridescenceLambert(f0, f90, iridescenceFresnel, iridescence, VoH);\n}\n\nvec3 iridescenceSpecularLobe(const in Surface surface, const in PixelInfo pixel, const in LightParams lightParams)\n{\n    float roughness = surface.roughness;\n    float D = distribution(roughness, lightParams.NoH, lightParams.h, pixel.normalWS);\n    float V = visibility(roughness, pixel.NoV, lightParams.NoL);\n\n    float iridescenceFactor = surface.iridescence;\n    vec3 iridescenceFresnel = pixel.iridescenceFresnel;\n    vec3 F = mix(fresnel(surface.f0, lightParams.LoH), iridescenceFresnel, vec3(iridescenceFactor));\n\n    return (D * V) * F;\n}\n    #endif // IRIDESCENCE\n\n    #ifdef CLEARCOAT\nfloat clearCoatLobe(const in Surface surface, const in PixelInfo pixel, const in LightParams lightParams)\n{\n    float roughness = surface.clearCoatRoughness;\n    float clearCoat = surface.clearCoat;\n    vec3 n = pixel.clearCoatNormal;\n    vec3 h = lightParams.h;\n    float LoH = lightParams.LoH;\n\n    float clearCoatNoH = lightParams.clearCoatNoH;\n\n    float D = distribution(roughness, clearCoatNoH, h, n);\n    float V = V_kelemen(LoH);\n\n    return D * V;\n}\n    #endif // CLEARCOAT\n\n    #ifdef SHEEN\nvec3 sheenLobe(const in Surface surface, const in PixelInfo pixel, const in LightParams lightParams)\n{\n    float roughness = surface.sheenRoughness;\n    float NoV = pixel.NoV;\n    float NoH = lightParams.NoH;\n    float NoL = lightParams.NoL;\n\n    float D = D_Charlie(roughness, NoH);\n    float V = V_Neubelt(NoV, NoL);\n    // F = 1.0\n    return D * V * surface.sheenColor;\n}\n    #endif // SHEEN\n\n    #ifdef ANISOTROPIC\nvec3 anisotropyLobe(const in Surface surface, const in PixelInfo pixel, const in LightParams lightParams)\n{\n    float anisotropy = surface.anisotropy;\n    float at = pixel.at;\n    float ab = pixel.ab;\n    vec3 anisotropicT = pixel.anisotropicT;\n    vec3 anisotropicB = pixel.anisotropicB;\n\n    float NoV = pixel.NoV;\n    float ToV = pixel.ToV;\n    float BoV = pixel.BoV;\n\n    vec3 h = lightParams.h;\n    float NoL = lightParams.NoL;\n    float NoH = lightParams.NoH;\n    float VoH = lightParams.VoH;\n    float ToL = lightParams.ToL;\n    float BoL = lightParams.BoL;\n\n    float V = V_SmithGGXCorrelated_Anisotropic(at, ab, ToV, BoV, ToL, BoL, NoV, NoL);\n    float D = D_GGX_Anisotropic(NoH, h, anisotropicT, anisotropicB, at, ab);\n    vec3 F = fresnel(surface.f0, surface.f90, lightParams.LoH);\n    return V * D * F;\n}\n    #endif // ANISOTROPIC\n\nvec3 PBRLighting(const in Surface surface, const in PixelInfo pixel, const in Light light)\n{\n    LightParams lightParams;\n    initLightParams(lightParams, pixel, light);\n\n    float NoL = lightParams.NoL;\n\n    #ifdef IRIDESCENCE\n    vec3 Fd = iridescenceDiffuseLobe(surface, pixel, lightParams);\n    vec3 Fr = iridescenceSpecularLobe(surface, pixel, lightParams);\n    #elif defined(ANISOTROPIC)\n    vec3 Fd = diffuseLobe(surface, pixel, lightParams);\n    vec3 Fr = anisotropyLobe(surface, pixel, lightParams);\n    #else\n    vec3 Fd = diffuseLobe(surface, pixel, lightParams);\n    vec3 Fr = specularLobe(surface, pixel, lightParams);\n    #endif\n\n    #ifdef TRANSMISSION\n    Fd *= 1.0 - surface.transmission;\n    #endif // TRANSMISSION\n\n    vec3 shading = (Fd + Fr * pixel.energyCompensation);\n\n    #ifdef SHEEN\n    vec3 fSheen = sheenLobe(surface, pixel, lightParams);\n    shading *= pixel.sheenScaling;\n    shading += fSheen;\n    #endif // SHEEN\n\n    #ifdef CLEARCOAT\n    float clearCoatNoL = lightParams.clearCoatNoL;\n    float LoH = lightParams.LoH;\n    // default IOR 1.5\n    float FccClearCoat = F_Schlick(0.04, 1.0, LoH) * surface.clearCoat;\n    float attenuation = 1.0 - FccClearCoat;\n    shading *= attenuation * NoL;\n\n    float clearcoat = clearCoatLobe(surface, pixel, lightParams) * FccClearCoat;\n    shading += clearcoat * clearCoatNoL;\n    // NoL has alread multiply\n    NoL = 1.0;\n    #endif // CLEARCOAT\n\n    return shading * light.color * NoL;\n}\n\n    // gi\n    #include \"PBRGI.glsl\";\n\n#endif // PBRLighting_lib";

    var BlitFS = "#define SHADER_NAME BlitFS\n\n#include \"Color.glsl\";\n#include \"FastApproximateAntiAliasing.glsl\";\n\nvarying vec2 v_Texcoord0;\n\nvoid main()\n{\n#ifdef FXAA\n    gl_FragColor = FXAAMain(u_MainTex, v_Texcoord0, u_MainTex_TexelSize.zw);\n#else\n    vec4 mainColor = texture2D(u_MainTex, v_Texcoord0);\n    #ifdef Gamma_u_MainTex\n    mainColor = gammaToLinear(mainColor);\n    #endif // Gamma_u_AlbedoTexture\n    gl_FragColor = mainColor;\n#endif\n\n    gl_FragColor = outputTransform(gl_FragColor);\n}\n";

    var FXAA = "#if !defined(FXAA_lib)\n    #define FXAA_lib\n#ifdef FXAA\n    #define EDGE_THRESHOLD_MIN 0.0312\n    #define EDGE_THRESHOLD_MAX 0.125\n    #define QUALITY(q)\t       ((q) < 5 ? 1.0 : ((q) > 5 ? ((q) < 10 ? 2.0 : ((q) < 11 ? 4.0 : 8.0)) : 1.5))\n    #define ITERATIONS\t       12\n    #define SUBPIXEL_QUALITY   0.75\n\nfloat rgb2luma(in vec3 rgb)\n{\n    return dot(rgb, vec3(0.299, 0.587, 0.114));\n}\n\nvec3 textureOffsetbyScreenSize(in sampler2D mainTex, in vec2 uv, in vec2 offset, in vec2 inverseScreenSize)\n{\n    vec2 sampleruv = uv + inverseScreenSize * offset; // u_texturesize表示每个像素的偏移量\n    return texture2D(mainTex, sampleruv).rgb;\n}\n\nvec4 FXAAMain(in sampler2D mainTex, in vec2 texuv, in vec2 inverseScreenSize)\n{\n\n    vec4 mainColor = texture2D(mainTex, texuv);\n    vec3 colorCenter = mainColor.rgb;\n    // Luma at the current fragment\n    float lumaCenter = rgb2luma(colorCenter);\n\n    // Luma at the four direct neighbours of the current fragment.\n    float lumaDown = rgb2luma(textureOffsetbyScreenSize(mainTex, texuv, vec2(0, -1), inverseScreenSize));\n    float lumaUp = rgb2luma(textureOffsetbyScreenSize(mainTex, texuv, vec2(0, 1), inverseScreenSize));\n    float lumaLeft = rgb2luma(textureOffsetbyScreenSize(mainTex, texuv, vec2(-1, 0), inverseScreenSize));\n    float lumaRight = rgb2luma(textureOffsetbyScreenSize(mainTex, texuv, vec2(1, 0), inverseScreenSize));\n\n    // Find the maximum and minimum luma around the current fragment.\n    float lumaMin = min(lumaCenter, min(min(lumaDown, lumaUp), min(lumaLeft, lumaRight)));\n    float lumaMax = max(lumaCenter, max(max(lumaDown, lumaUp), max(lumaLeft, lumaRight)));\n\n    // Compute the delta.\n    float lumaRange = lumaMax - lumaMin;\n\n    // If the luma variation is lower that a threshold (or if we are in a really dark area), we are not on an edge, don't perform any AA.\n    if (lumaRange < max(EDGE_THRESHOLD_MIN, lumaMax * EDGE_THRESHOLD_MAX))\n\t{\n\t    return mainColor;\n\t}\n\n    // Query the 4 remaining corners lumas.\n    float lumaDownLeft = rgb2luma(textureOffsetbyScreenSize(mainTex, texuv, vec2(-1, -1), inverseScreenSize));\n    float lumaUpRight = rgb2luma(textureOffsetbyScreenSize(mainTex, texuv, vec2(1, 1), inverseScreenSize));\n    float lumaUpLeft = rgb2luma(textureOffsetbyScreenSize(mainTex, texuv, vec2(-1, 1), inverseScreenSize));\n    float lumaDownRight = rgb2luma(textureOffsetbyScreenSize(mainTex, texuv, vec2(1, -1), inverseScreenSize));\n\n    // Combine the four edges lumas (using intermediary variables for future computations with the same values).\n    float lumaDownUp = lumaDown + lumaUp;\n    float lumaLeftRight = lumaLeft + lumaRight;\n\n    // Same for corners\n    float lumaLeftCorners = lumaDownLeft + lumaUpLeft;\n    float lumaDownCorners = lumaDownLeft + lumaDownRight;\n    float lumaRightCorners = lumaDownRight + lumaUpRight;\n    float lumaUpCorners = lumaUpRight + lumaUpLeft;\n\n    // Compute an estimation of the gradient along the horizontal and vertical axis.\n    float edgeHorizontal = abs(-2.0 * lumaLeft + lumaLeftCorners) + abs(-2.0 * lumaCenter + lumaDownUp) * 2.0 + abs(-2.0 * lumaRight + lumaRightCorners);\n    float edgeVertical = abs(-2.0 * lumaUp + lumaUpCorners) + abs(-2.0 * lumaCenter + lumaLeftRight) * 2.0 + abs(-2.0 * lumaDown + lumaDownCorners);\n\n    // Is the local edge horizontal or vertical ?\n    bool isHorizontal = (edgeHorizontal >= edgeVertical);\n\n    // Choose the step size (one pixel) accordingly.\n    float stepLength = isHorizontal ? inverseScreenSize.y : inverseScreenSize.x;\n\n    // Select the two neighboring texels lumas in the opposite direction to the local edge.\n    float luma1 = isHorizontal ? lumaDown : lumaLeft;\n    float luma2 = isHorizontal ? lumaUp : lumaRight;\n    // Compute gradients in this direction.\n    float gradient1 = luma1 - lumaCenter;\n    float gradient2 = luma2 - lumaCenter;\n\n    // Which direction is the steepest ?\n    bool is1Steepest = abs(gradient1) >= abs(gradient2);\n\n    // Gradient in the corresponding direction, normalized.\n    float gradientScaled = 0.25 * max(abs(gradient1), abs(gradient2));\n\n    // Average luma in the correct direction.\n    float lumaLocalAverage = 0.0;\n    if (is1Steepest)\n\t{\n\t    // Switch the direction\n\t    stepLength = -stepLength;\n\t    lumaLocalAverage = 0.5 * (luma1 + lumaCenter);\n\t}\n    else\n\t{\n\t    lumaLocalAverage = 0.5 * (luma2 + lumaCenter);\n\t}\n\n    // Shift UV in the correct direction by half a pixel.\n    vec2 currentUv = texuv;\n    if (isHorizontal)\n\t{\n\t    currentUv.y += stepLength * 0.5;\n\t}\n    else\n\t{\n\t    currentUv.x += stepLength * 0.5;\n\t}\n\n    // Compute offset (for each iteration step) in the right direction.\n    vec2 offset = isHorizontal ? vec2(inverseScreenSize.x, 0.0) : vec2(0.0, inverseScreenSize.y);\n    // Compute UVs to explore on each side of the edge, orthogonally. The QUALITY allows us to step faster.\n    vec2 uv1 = currentUv - offset * QUALITY(0);\n    vec2 uv2 = currentUv + offset * QUALITY(0);\n\n    // Read the lumas at both current extremities of the exploration segment, and compute the delta wrt to the local average luma.\n    float lumaEnd1 = rgb2luma(textureOffsetbyScreenSize(mainTex, uv1, vec2(0.0, 0.0), inverseScreenSize));\n    float lumaEnd2 = rgb2luma(textureOffsetbyScreenSize(mainTex, uv2, vec2(0.0, 0.0), inverseScreenSize));\n    lumaEnd1 -= lumaLocalAverage;\n    lumaEnd2 -= lumaLocalAverage;\n\n    // If the luma deltas at the current extremities is larger than the local gradient, we have reached the side of the edge.\n    bool reached1 = abs(lumaEnd1) >= gradientScaled;\n    bool reached2 = abs(lumaEnd2) >= gradientScaled;\n    bool reachedBoth = reached1 && reached2;\n\n    // If the side is not reached, we continue to explore in this direction.\n    if (!reached1)\n\t{\n\t    uv1 -= offset * QUALITY(1);\n\t}\n    if (!reached2)\n\t{\n\t    uv2 += offset * QUALITY(1);\n\t}\n\n    // If both sides have not been reached, continue to explore.\n    if (!reachedBoth)\n\t{\n\n\t    for (int i = 2; i < ITERATIONS; i++)\n\t\t{\n\t\t    // If needed, read luma in 1st direction, compute delta.\n\t\t    if (!reached1)\n\t\t\t{\n\t\t\t    lumaEnd1 = rgb2luma(textureOffsetbyScreenSize(mainTex, uv1, vec2(0.0, 0.0), inverseScreenSize));\n\t\t\t    lumaEnd1 = lumaEnd1 - lumaLocalAverage;\n\t\t\t}\n\t\t    // If needed, read luma in opposite direction, compute delta.\n\t\t    if (!reached2)\n\t\t\t{\n\t\t\t    lumaEnd2 = rgb2luma(textureOffsetbyScreenSize(mainTex, uv2, vec2(0.0, 0.0), inverseScreenSize));\n\t\t\t    lumaEnd2 = lumaEnd2 - lumaLocalAverage;\n\t\t\t}\n\t\t    // If the luma deltas at the current extremities is larger than the local gradient, we have reached the side of the edge.\n\t\t    reached1 = abs(lumaEnd1) >= gradientScaled;\n\t\t    reached2 = abs(lumaEnd2) >= gradientScaled;\n\t\t    reachedBoth = reached1 && reached2;\n\n\t\t    // If the side is not reached, we continue to explore in this direction, with a variable quality.\n\t\t    if (!reached1)\n\t\t\t{\n\t\t\t    uv1 -= offset * QUALITY(i);\n\t\t\t}\n\t\t    if (!reached2)\n\t\t\t{\n\t\t\t    uv2 += offset * QUALITY(i);\n\t\t\t}\n\n\t\t    // If both sides have been reached, stop the exploration.\n\t\t    if (reachedBoth)\n\t\t\t{\n\t\t\t    break;\n\t\t\t}\n\t\t}\n\t}\n\n    // Compute the distances to each side edge of the edge (!).\n    float distance1 = isHorizontal ? (texuv.x - uv1.x) : (texuv.y - uv1.y);\n    float distance2 = isHorizontal ? (uv2.x - texuv.x) : (uv2.y - texuv.y);\n\n    // In which direction is the side of the edge closer ?\n    bool isDirection1 = distance1 < distance2;\n    float distanceFinal = min(distance1, distance2);\n\n    // Thickness of the edge.\n    float edgeThickness = (distance1 + distance2);\n\n    // Is the luma at center smaller than the local average ?\n    bool isLumaCenterSmaller = lumaCenter < lumaLocalAverage;\n\n    // If the luma at center is smaller than at its neighbour, the delta luma at each end should be positive (same variation).\n    bool correctVariation1 = (lumaEnd1 < 0.0) != isLumaCenterSmaller;\n    bool correctVariation2 = (lumaEnd2 < 0.0) != isLumaCenterSmaller;\n\n    // Only keep the result in the direction of the closer side of the edge.\n    bool correctVariation = isDirection1 ? correctVariation1 : correctVariation2;\n\n    // UV offset: read in the direction of the closest side of the edge.\n    float pixelOffset = -distanceFinal / edgeThickness + 0.5;\n\n    // If the luma variation is incorrect, do not offset.\n    float finalOffset = correctVariation ? pixelOffset : 0.0;\n\n    // Sub-pixel shifting\n    // Full weighted average of the luma over the 3x3 neighborhood.\n    float lumaAverage = (1.0 / 12.0) * (2.0 * (lumaDownUp + lumaLeftRight) + lumaLeftCorners + lumaRightCorners);\n    // Ratio of the delta between the global average and the center luma, over the luma range in the 3x3 neighborhood.\n    float subPixelOffset1 = clamp(abs(lumaAverage - lumaCenter) / lumaRange, 0.0, 1.0);\n    float subPixelOffset2 = (-2.0 * subPixelOffset1 + 3.0) * subPixelOffset1 * subPixelOffset1;\n    // Compute a sub-pixel offset based on this delta.\n    float subPixelOffsetFinal = subPixelOffset2 * subPixelOffset2 * SUBPIXEL_QUALITY;\n\n    // Pick the biggest of the two offsets.\n    finalOffset = max(finalOffset, subPixelOffsetFinal);\n\n    // Compute the final UV coordinates.\n    vec2 finalUv = texuv;\n    if (isHorizontal)\n\t{\n\t    finalUv.y += finalOffset * stepLength;\n\t}\n    else\n\t{\n\t    finalUv.x += finalOffset * stepLength;\n\t}\n\n    // Read the color at the new UV coordinates, and use it.\n    return texture2D(mainTex, finalUv);\n}\n#endif//FXAA\n#endif // Color_lib\n";

    var ColorGradingGLSL = "#if !defined(ColorGrading_lib)\n    #define ColorGrading_lib\n\nconst float ACEScc_MAX = 1.4679964;\nconst float ACEScc_MIDGRAY = 0.4135884;\n\nconst float LogC_cut = 0.011361;\nconst float LogC_a = 5.555556;\nconst float LogC_b = 0.047996;\nconst float LogC_c = 0.244161;\nconst float LogC_d = 0.386036;\nconst float LogC_e = 5.301883;\nconst float LogC_f = 0.092819;\n\nfloat linearToLogC(float x)\n{\n    float o;\n    if (x > LogC_cut)\n\t{\n\t    o = LogC_c * log10(max(LogC_a * x + LogC_b, 0.0)) + LogC_d;\n\t}\n    else\n\t{\n\t    o = LogC_e * x + LogC_f;\n\t}\n    return o;\n}\n\nvec3 linearToLogC(vec3 x)\n{\n    vec3 logc;\n    logc.x = linearToLogC(x.x);\n    logc.y = linearToLogC(x.y);\n    logc.z = linearToLogC(x.z);\n    return logc;\n}\n\nfloat logCToLinear(float x)\n{\n    float o;\n    if (x > LogC_e * LogC_cut + LogC_f)\n\to = (pow(10.0, (x - LogC_d) / LogC_c) - LogC_b) / LogC_a;\n    else\n\to = (x - LogC_f) / LogC_e;\n    return o;\n}\n\nvec3 logCToLinear(vec3 x)\n{\n    vec3 linear;\n    linear.x = logCToLinear(x.x);\n    linear.y = logCToLinear(x.y);\n    linear.z = logCToLinear(x.z);\n    return linear;\n}\n\n// Hue, Saturation, Value\n// Ranges:\n//  Hue [0.0, 1.0]\n//  Sat [0.0, 1.0]\n//  Lum [0.0, HALF_MAX]\nvec3 RgbToHsv(vec3 c)\n{\n    const vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);\n    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));\n    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));\n    float d = q.x - min(q.w, q.y);\n    const float e = 1.0e-4;\n    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);\n}\n\nvec3 HsvToRgb(vec3 c)\n{\n    const vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);\n    vec3 p = abs(fract(vec3(c.x) + K.xyz) * 6.0 - K.www);\n    return c.z * mix(vec3(K.x) , saturate(p - vec3(K.x)), c.y);\n}\n\nfloat RotateHue(float value, float low, float hi)\n{\n    return (value < low)\n            ? value + hi\n            : (value > hi)\n                ? value - hi\n                : value;\n}\n\n\nconst mat3 Linear_to_LMS_MAT = mat3(\n    vec3(3.90405e-1, 7.08416e-2, 2.31082e-2),\n    vec3(5.49941e-1, 9.63172e-1, 1.28021e-1),\n    vec3(8.92632e-3, 1.35775e-3, 9.36245e-1));\n\nconst mat3 LMS_to_Linear_MAT = mat3(\n    vec3(2.85847e+0, -2.10182e-1, -4.18120e-2),\n    vec3(-1.62879e+0, 1.15820e+0, -1.18169e-1),\n    vec3(-2.48910e-2, 3.24281e-4, 1.06867e+0));\n\n// white balance\nuniform vec3 u_ColorBalance;\n\n// split toning\nuniform vec4 u_SplitShadows;\nuniform vec3 u_Splithighlights;\n\n// shadows, midtones, highlights\nuniform vec3 u_Shadows;\nuniform vec3 u_Midtones;\nuniform vec3 u_Highlights;\nuniform vec4 u_Limits;\n\n// lift, gamma, gain\nuniform vec3 u_Lift;\nuniform vec3 u_Gamma;\nuniform vec3 u_Gain;\n\n//color adjusted\nuniform vec4 u_ColorFilter;\nuniform vec4 u_HueSatCon;\n\nfloat luminance(in vec3 color)\n{\n    #ifdef ACES\n    float luma = dot(color, AP1_RGB2Y);\n    #else\n    float luma = dot(color, vec3(0.2126729, 0.7151522, 0.0721750));\n    #endif // ACES\n    return luma;\n}\n\nvec3 softlight(vec3 base, vec3 blend)\n{\n    vec3 r1 = 2.0 * base * blend + base * base * (1.0 - 2.0 * blend);\n    vec3 r2 = sqrt(base) * (2.0 * blend - 1.0) + 2.0 * base * (1.0 - blend);\n    vec3 t = step(0.5, blend);\n    return r2 * t + (1.0 - t) * r1;\n}\n\n// input linear sRGB\n// if ACES tonemap, calculate in ACEScg, return ACEScg\n// else calculate in logC, return linear sRGB\nvec3 colorGrade(in vec3 color)\n{\n    // White balance in LMS space\n    vec3 colorLMS = Linear_to_LMS_MAT * color;\n    colorLMS *= u_ColorBalance.xyz;\n    color = LMS_to_Linear_MAT * colorLMS;\n\n    // Do contrast in log after white balance\n    #ifdef ACES\n        vec3 colorLog = ACES_to_ACEScc(sRGB_to_AP0_MAT * color);\n    #else\n        vec3 colorLog = linearToLogC(color);\n    #endif\n    \n    colorLog = (colorLog - vec3(ACEScc_MIDGRAY)) * u_HueSatCon.z + vec3(ACEScc_MIDGRAY);\n\n\n    #ifdef ACES\n        //colorLinear = ACES_to_ACEScg(ACEScc_to_ACES(colorLog));\n        color = AP0_to_AP1_MAT * ACEScc_to_ACES(colorLog);\n    #else\n        color = logCToLinear(colorLog);\n    #endif // ACES\n\n    // Color filter is just an unclipped multiplier\n    color = color * u_ColorFilter.rgb;\n\n    color = max(vec3(0.0), color);\n\n    // split toning\n    float balance = u_SplitShadows.w;\n    vec3 gamma = linearToGamma(color);\n    float splitLuma = saturate(luminance(color)) + balance;\n    vec3 splitShadows = mix(vec3(0.5, 0.5, 0.5), u_SplitShadows.xyz, 1.0 - splitLuma);\n    vec3 splitHeighlights = mix(vec3(0.5, 0.5, 0.5), u_Splithighlights.xyz, splitLuma);\n    gamma = softlight(gamma, splitShadows);\n    gamma = softlight(gamma, splitHeighlights);\n    color = gammaToLinear(gamma);\n\n    // shadows, midtones, highlights\n    float luma = luminance(color);\n    float shadowFactor = 1.0 - smoothstep(u_Limits.x, u_Limits.y, luma);\n    float highlightsFactor = smoothstep(u_Limits.z, u_Limits.w, luma);\n    float midtonesFactor = 1.0 - shadowFactor - highlightsFactor;\n    color = color * u_Shadows.xyz * shadowFactor + color * u_Midtones.xyz * midtonesFactor + color * u_Highlights.xyz * highlightsFactor;\n\n    // Lift, gamma, gain\n    color = color * u_Gain.xyz + u_Lift.xyz;\n    color = sign(color) * pow(abs(color), u_Gamma.xyz);\n    \n    // HSV operations\n    vec3 hsv = RgbToHsv(color);\n    // Hue Shift & Hue Vs Hue\n    float hue = hsv.x + u_HueSatCon.x;\n    hsv.x = RotateHue(hsv.x, 0.0, 1.0);\n    color = HsvToRgb(hsv);\n\n    // Global saturation\n    luma = luminance(color);\n    color = vec3(luma) + (vec3(u_HueSatCon.y)) * (color - vec3(luma));\n    \n    return color;\n}\n\n#endif // ColorGrading_lib";

    var TonemappingGLSL = "#if !defined(Tonemapping_lib)\n    #define Tonemapping_lib\n\n// ACES Tonemapping color grading in ACEScg space\nvec3 tonemap(in vec3 ap1)\n{\n    vec3 color = ap1;\n\n    #ifdef ACES\n    vec3 aces = AP1_to_AP0_MAT * color;\n    vec3 oces = RRT(aces);\n    color = ODT_sRGB_100nits(oces);\n    #endif // ACES\n\n    // todo other tonemap\n\n    return color;\n}\n\n#endif // Tonemapping_lib";

    var LUTGLSL = "#if !defined(LUT_lib)\n    #define LUT_lib\n\n// scaleOffset = (1 / lut_width, 1 / lut_height, lut_height - 1)\nvec3 applyLut(sampler2D lut, vec3 uvw, vec3 scaleOffset)\n{\n    uvw.z *= scaleOffset.z;\n\n    float shift = floor(uvw.z);\n    uvw.xy = uvw.xy * scaleOffset.z * scaleOffset.xy + scaleOffset.xy * 0.5;\n    uvw.x += shift * scaleOffset.y;\n\n    uvw.xyz = mix(\n\ttexture2DLodEXT(lut, uvw.xy, 0.0).rgb,\n\ttexture2DLodEXT(lut, uvw.xy + vec2(scaleOffset.y, 0.0), 0.0).rgb,\n\tuvw.z - shift);\n    return uvw;\n}\n\n#endif // LUT_lib";

