            TrailFilter.WIDTHCURVE = Laya.Shader3D.propertyNameToID("u_WidthCurve");
            TrailFilter.WIDTHCURVEKEYLENGTH = Laya.Shader3D.propertyNameToID("u_WidthCurveKeyLength");
            const spriteParms = Laya.LayaGL.renderDeviceFactory.createGlobalUniformMap("TrailRender");
            spriteParms.addShaderUniform(TrailFilter.CURTIME, "u_CurTime", exports.ShaderDataType.Float);
            spriteParms.addShaderUniform(TrailFilter.LIFETIME, "u_LifeTime", exports.ShaderDataType.Float);
            spriteParms.addShaderUniform(TrailFilter.WIDTHCURVE, "u_WidthCurve", exports.ShaderDataType.Buffer);
            spriteParms.addShaderUniform(TrailFilter.WIDTHCURVEKEYLENGTH, "u_WidthCurveKeyLength", exports.ShaderDataType.Int);
