    var BloomUpsampleTentPS = "#define SHADER_NAME BloomUpSampleTentFS\n\n#include \"Color.glsl\";\n#include \"Colors.glsl\";\n#include \"Sampling.glsl\";\n\nvarying vec2 v_Texcoord0;\n\nmediump vec4 combine(mediump vec4 bloom, vec2 uv)\n{\n    mediump vec4 color = texture2D(u_BloomTex, uv);\n#ifdef Gamma_u_BloomTex\n    color = gammaToLinear(color);\n#endif // Gamma_u_BloomTex\n    return bloom + color;\n}\n\nvoid fragUpsampleTent()\n{\n    mediump vec4 bloom = upsampleTent(u_MainTex, v_Texcoord0, u_MainTex_TexelSize.xy, vec4(u_SampleScale));\n    gl_FragColor = combine(bloom, v_Texcoord0);\n}\n\nvoid main()\n{\n    fragUpsampleTent();\n\n    gl_FragColor = outputTransform(gl_FragColor);\n}";

    var CompositePS = "#define SHADER_NAME CompositeFS\n\n#include \"Color.glsl\";\n#include \"Colors.glsl\";\n#include \"Sampling.glsl\";\n\nvarying vec2 v_Texcoord0;\n\nvoid main()\n{\n    vec4 autoExposureSampler = texture2D(u_AutoExposureTex, v_Texcoord0);\n#ifdef Gamma_u_AutoExposureTex\n    autoExposureSampler = gammaToLinear(autoExposureSampler);\n#endif // Gamma_u_AutoExposureTex\n    mediump float autoExposure = autoExposureSampler.r;\n\n    mediump vec4 color = vec4(0.0);\n    color = texture2D(u_MainTex, v_Texcoord0);\n#ifdef Gamma_u_MainTex\n    color = gammaToLinear(color);\n#endif // Gamma_u_MainTex\n\n    color.rgb *= autoExposure;\n\n#if defined(BLOOM) || defined(BLOOM_LOW)\n    #ifdef BLOOM\n    mediump vec4 bloom = upsampleTent(u_BloomTex, v_Texcoord0, u_BloomTex_TexelSize.xy, vec4(u_Bloom_Settings.x));\n    #else\n    mediump vec4 bloom = upsampleBox(u_BloomTex, v_Texcoord0, u_BloomTex_TexelSize.xy, vec4(u_Bloom_Settings.x));\n    #endif\n\n    // UVs should be Distort(uv * u_Bloom_DirtTileOffset.xy + u_Bloom_DirtTileOffset.zw)\n    // but considering we use a cover-style scale on the dirt texture the difference\n    // isn't massive so we chose to save a few ALUs here instead in case lens distortion\n    // is active\n    mediump vec4 dirt = vec4(texture2D(u_Bloom_DirtTex, v_Texcoord0 * u_Bloom_DirtTileOffset.xy + u_Bloom_DirtTileOffset.zw).rgb, 0.0);\n    #ifdef Gamma_u_Bloom_DirtTex\n    dirt = gammaToLinear(dirt);\n    #endif // Gamma_u_Bloom_DirtTex\n\n    // Additive bloom (artist friendly)\n    bloom *= u_Bloom_Settings.y;\n    dirt *= u_Bloom_Settings.z;\n    mediump vec4 bloomColor = u_Bloom_Color;\n    color += bloom * bloomColor;\n    color += dirt * bloom;\n#endif\n\n    mediump vec4 finalColor = color;\n    // finalColor = linearToSRGB(finalColor);\n    // finalColor.rgb = Dither(finalColor.rgb, v_Texcoord0);//TODO:抖动\n    gl_FragColor = finalColor;\n\n    gl_FragColor = outputTransform(gl_FragColor);\n}";

    var CompositeVS = "#define SHADER_NAME CompositeVS\nvarying vec2 v_Texcoord0;\nvec4 remapPositionZ(vec4 position)\n{\n    #ifdef BLITSCREEN_INVERTY\n    position.y = -position.y;\n    #endif\n    return position;\n}\nvoid main() {\n\tgl_Position = vec4(a_PositionTexcoord.xy, 0.0, 1.0);\n\tv_Texcoord0 = a_PositionTexcoord.zw;\n\tgl_Position = remapPositionZ(gl_Position);\n}";

    var SamplingGLSL = "\n// todo only sampler u_MainTex\nvec4 samplerTex(sampler2D tex, vec2 uv)\n{\n    vec4 mainSampler = texture2D(tex, uv);\n#ifdef Gamma_u_MainTex\n    mainSampler = gammaToLinear(mainSampler);\n#endif // Gamma_u_MainTex\n\n    return mainSampler;\n}\n\n// Better, temporally stable box filtering\n// [Jimenez14] http://goo.gl/eomGso\n// . . . . . . .\n// . A . B . C .\n// . . D . E . .\n// . F . G . H .\n// . . I . J . .\n// . K . L . M .\n// . . . . . . .\nmediump vec4 downsampleBox13Tap(sampler2D tex, vec2 uv, vec2 texelSize)\n{\n    mediump vec4 A = samplerTex(tex, uv + texelSize * vec2(-1.0, -1.0));\n    mediump vec4 B = samplerTex(tex, uv + texelSize * vec2(0.0, -1.0));\n    mediump vec4 C = samplerTex(tex, uv + texelSize * vec2(1.0, -1.0));\n    mediump vec4 D = samplerTex(tex, uv + texelSize * vec2(-0.5, -0.5));\n    mediump vec4 E = samplerTex(tex, uv + texelSize * vec2(0.5, -0.5));\n    mediump vec4 F = samplerTex(tex, uv + texelSize * vec2(-1.0, 0.0));\n    mediump vec4 G = samplerTex(tex, uv);\n    mediump vec4 H = samplerTex(tex, uv + texelSize * vec2(1.0, 0.0));\n    mediump vec4 I = samplerTex(tex, uv + texelSize * vec2(-0.5, 0.5));\n    mediump vec4 J = samplerTex(tex, uv + texelSize * vec2(0.5, 0.5));\n    mediump vec4 K = samplerTex(tex, uv + texelSize * vec2(-1.0, 1.0));\n    mediump vec4 L = samplerTex(tex, uv + texelSize * vec2(0.0, 1.0));\n    mediump vec4 M = samplerTex(tex, uv + texelSize * vec2(1.0, 1.0));\n\n    mediump vec2 scale = vec2(0.5, 0.125);\n    mediump vec2 div = (1.0 / 4.0) * scale;\n\n    mediump vec4 o = (D + E + I + J) * div.x;\n    o += (A + B + G + F) * div.y;\n    o += (B + C + H + G) * div.y;\n    o += (F + G + L + K) * div.y;\n    o += (G + H + M + L) * div.y;\n\n    return o;\n}\n\n// Standard box filtering\nmediump vec4 downsampleBox4Tap(sampler2D tex, vec2 uv, vec2 texelSize)\n{\n    vec4 d = texelSize.xyxy * vec4(-1.0, -1.0, 1.0, 1.0);\n\n    mediump vec4 s = samplerTex(tex, uv + d.xy);\n    s += samplerTex(tex, uv + d.zy);\n    s += samplerTex(tex, uv + d.xw);\n    s += samplerTex(tex, uv + d.zw);\n\n    return s * (1.0 / 4.0);\n}\n\n// 9-tap bilinear upsampler (tent filter)\n// . . . . . . .\n// . 1 . 2 . 1 .\n// . . . . . . .\n// . 2 . 4 . 2 .\n// . . . . . . .\n// . 1 . 2 . 1 .\n// . . . . . . .\nmediump vec4 upsampleTent(sampler2D tex, vec2 uv, vec2 texelSize, vec4 sampleScale)\n{\n    vec4 d = texelSize.xyxy * vec4(1.0, 1.0, -1.0, 0.0) * sampleScale;\n\n    mediump vec4 s = samplerTex(tex, uv - d.xy);\n    s += samplerTex(tex, uv - d.wy) * 2.0;\n    s += samplerTex(tex, uv - d.zy);\n\n    s += samplerTex(tex, uv + d.zw) * 2.0;\n    s += samplerTex(tex, uv) * 4.0;\n    s += samplerTex(tex, uv + d.xw) * 2.0;\n\n    s += samplerTex(tex, uv + d.zy);\n    s += samplerTex(tex, uv + d.wy) * 2.0;\n    s += samplerTex(tex, uv + d.xy);\n\n    return s * (1.0 / 16.0);\n}\n\n// Standard box filtering\nmediump vec4 upsampleBox(sampler2D tex, vec2 uv, vec2 texelSize, vec4 sampleScale)\n{\n    vec4 d = texelSize.xyxy * vec4(-1.0, -1.0, 1.0, 1.0) * 0.5 * sampleScale;\n\n    mediump vec4 s = samplerTex(tex, uv + d.xy);\n    s += samplerTex(tex, uv + d.zy);\n    s += samplerTex(tex, uv + d.xw);\n    s += samplerTex(tex, uv + d.zw);\n\n    return s * (1.0 / 4.0);\n}";

    var StdLibGLSL = "#define HALF_MAX       65504.0 // (2 - 2^-10) * 2^15\n\n#define FLT_EPSILON    1.192092896e-07 // Smallest positive number, such that 1.0 + FLT_EPSILON != 1.0\n\nmediump vec4 safeHDR(mediump vec4 c)\n{\n    return min(c, HALF_MAX);\n}\n\nfloat max3(float a, float b, float c)\n{\n    return max(max(a, b), c);\n}\n\nvec3 positivePow(vec3 base, vec3 power)\n{\n    return pow(max(abs(base), vec3(FLT_EPSILON, FLT_EPSILON, FLT_EPSILON)), power);\n}";

    var ColorsGLSL = "#include \"StdLib.glsl\";\n\n#define EPSILON 1.0e-4\n\n// Quadratic color thresholding\n// curve = (threshold - knee, knee * 2, 0.25 / knee)\nmediump vec4 quadraticThreshold(mediump vec4 color, mediump float threshold, mediump vec3 curve) {\n\t// Pixel brightness\n\tmediump float br = max3(color.r, color.g, color.b);\n\n\t// Under-threshold part: quadratic curve\n\tmediump float rq = clamp(br - curve.x, 0.0, curve.y);\n\trq = curve.z * rq * rq;\n\n\t// Combine and apply the brightness response curve.\n\tcolor *= max(rq, br - threshold) / max(br, EPSILON);\n\n\treturn color;\n}\n\n\n\n//\n// sRGB transfer functions\n// Fast path ref: http://chilliant.blogspot.com.au/2012/08/srgb-approximations-for-hlsl.html?m=1\n//\n// mediump vec3 sRGBToLinear(mediump vec3 c) {\n// \t#ifdef USE_VERY_FAST_SRGB\n// \t\treturn c * c;\n// \t#elif defined(USE_FAST_SRGB)\n// \t\treturn c * (c * (c * 0.305306011 + 0.682171111) + 0.012522878);\n// \t#else\n// \t\tmediump vec3 linearRGBLo = c / 12.92;\n// \t\tmediump vec3 power=vec3(2.4, 2.4, 2.4);\n// \t\tmediump vec3 linearRGBHi = positivePow((c + 0.055) / 1.055, power);\n// \t\tmediump vec3 linearRGB =vec3((c.r<=0.04045) ? linearRGBLo.r : linearRGBHi.r,(c.g<=0.04045) ? linearRGBLo.g : linearRGBHi.g,(c.b<=0.04045) ? linearRGBLo.b : linearRGBHi.b);\n// \t\treturn linearRGB;\n// \t#endif\n// }\n\n// mediump vec4 sRGBToLinear(mediump vec4 c){\n//     return vec4(sRGBToLinear(c.rgb), c.a);\n// }\n\n\n\n// mediump vec3 linearToSRGB(mediump vec3 c) {\n// \t#ifdef USE_VERY_FAST_SRGB\n// \t\treturn sqrt(c);\n// \t#elif defined(USE_FAST_SRGB)\n// \t\treturn max(1.055 * PositivePow(c, 0.416666667) - 0.055, 0.0);\n// \t#else\n// \t\tmediump vec3 sRGBLo = c * 12.92;\n// \t\tmediump vec3 power=vec3(1.0 / 2.4, 1.0 / 2.4, 1.0 / 2.4);\n// \t\tmediump vec3 sRGBHi = (positivePow(c, power) * 1.055) - 0.055;\n// \t\tmediump vec3 sRGB =vec3((c.r<=0.0031308) ? sRGBLo.r : sRGBHi.r,(c.g<=0.0031308) ? sRGBLo.g : sRGBHi.g,(c.b<=0.0031308) ? sRGBLo.b : sRGBHi.b);\n// \t\treturn sRGB;\n// \t#endif\n// }\n\n// mediump vec4 linearToSRGB(mediump vec4 c){\n//     return vec4(linearToSRGB(c.rgb), c.a);\n// }";

