        static load(url, complete) {
            Laya.ILaya.loader.load(url).then((res) => {
                if (complete) {
                    let ret;
                    if (res) {
                        let scene = res.create();
                        if (scene instanceof Laya.Scene)
                            ret = scene._scene3D;
                        else
                            ret = scene;
                    }
                    complete.runWith([ret]);
                }
            });
        }
